  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), (2 * pyattr(pyattr(self, \"N\"), \"x\")))", e)
  .run("actuator <- ForceActuator(pyattr(self, \"force\"), pyattr(self, \"pathway\"))", e)
  .run("expected <- list(tup(pyattr(self, \"pA\"), ((-pyattr(self, \"force\")) * pyattr(pyattr(self, \"N\"), \"x\"))), tup(pyattr(self, \"pB\"), (pyattr(self, \"force\") * pyattr(pyattr(self, \"N\"), \"x\"))))", e)
  expect_equal(.case("pycall(actuator, \"to_loads\")", e), "[(pA, - F*N.x), (pB, F*N.x)]")
})

test_that("mechanics/tests/test_actuator.py::TestForceActuator::test_to_loads_2D_pathway matches SymPy", {
