  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), ((2 * pyattr(self, \"q1\")) * pyattr(pyattr(self, \"N\"), \"x\")))", e)
  .run("actuator <- ForceActuator(pyattr(self, \"force\"), pyattr(self, \"pathway\"))", e)
  .run("expected <- list(tup(pyattr(self, \"pA\"), (((-pyattr(self, \"force\")) * (pyattr(self, \"q1\") / sqrt(pypow(pyattr(self, \"q1\"), 2)))) * pyattr(pyattr(self, \"N\"), \"x\"))), tup(pyattr(self, \"pB\"), ((pyattr(self, \"force\") * (pyattr(self, \"q1\") / sqrt(pypow(pyattr(self, \"q1\"), 2)))) * pyattr(pyattr(self, \"N\"), \"x\"))))", e)
  expect_equal(.case("pycall(actuator, \"to_loads\")", e), "[(pA, - F*q1(t)/sqrt(q1(t)^2)*N.x), (pB, F*q1(t)/sqrt(q1(t)^2)*N.x)]")
})

test_that("mechanics/tests/test_actuator.py::TestForceActuator::test_to_loads_3D_pathway matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"force\", Symbol(\"F\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\")))", e)
  .run("pysetattr(self, \"q1\", dynamicsymbols(\"q1\"))", e)
  .run("pysetattr(self, \"q2\", dynamicsymbols(\"q2\"))", e)
  .run("pysetattr(self, \"q3\", dynamicsymbols(\"q3\"))", e)
  .run("pysetattr(self, \"q1d\", dynamicsymbols(\"q1\", 1))", e)
  .run("pysetattr(self, \"q2d\", dynamicsymbols(\"q2\", 1))", e)
  .run("pysetattr(self, \"q3d\", dynamicsymbols(\"q3\", 1))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), (((pyattr(self, \"q1\") * pyattr(pyattr(self, \"N\"), \"x\")) - (pyattr(self, \"q2\") * pyattr(pyattr(self, \"N\"), \"y\"))) + ((2 * pyattr(self, \"q3\")) * pyattr(pyattr(self, \"N\"), \"z\"))))", e)
  .run("actuator <- ForceActuator(pyattr(self, \"force\"), pyattr(self, \"pathway\"))", e)
  .run("length <- sqrt(((pypow(pyattr(self, \"q1\"), 2) + pypow(pyattr(self, \"q2\"), 2)) + (4 * pypow(pyattr(self, \"q3\"), 2))))", e)
  .run("pO_force <- ((((((-pyattr(self, \"force\")) * pyattr(self, \"q1\")) * pyattr(pyattr(self, \"N\"), \"x\")) / length) + (((pyattr(self, \"force\") * pyattr(self, \"q2\")) * pyattr(pyattr(self, \"N\"), \"y\")) / length)) - ((((2 * pyattr(self, \"force\")) * pyattr(self, \"q3\")) * pyattr(pyattr(self, \"N\"), \"z\")) / length))", e)
  .run("pI_force <- (((((pyattr(self, \"force\") * pyattr(self, \"q1\")) * pyattr(pyattr(self, \"N\"), \"x\")) / length) - (((pyattr(self, \"force\") * pyattr(self, \"q2\")) * pyattr(pyattr(self, \"N\"), \"y\")) / length)) + ((((2 * pyattr(self, \"force\")) * pyattr(self, \"q3\")) * pyattr(pyattr(self, \"N\"), \"z\")) / length))", e)
  .run("expected <- list(tup(pyattr(self, \"pA\"), pO_force), tup(pyattr(self, \"pB\"), pI_force))", e)
  expect_equal(.case("pycall(actuator, \"to_loads\")", e), "[(pA, - F*q1(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.x + F*q2(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.y - 2*F*q3(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.z), (pB, F*q1(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.x - F*q2(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.y + 2*F*q3(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.z)]")
})

test_that("mechanics/tests/test_actuator.py::TestLinearSpring::test_valid_constructor[0] matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("stiffness <- 1", e)
  .run("expected_stiffness <- S_One", e)
  .run("equilibrium_length <- 0", e)
  .run("expected_equilibrium_length <- S_Zero", e)
  .run("force <- (-sqrt(pypow(dynamicsymbols(\"q\"), 2)))", e)
  .run("pysetattr(self, \"stiffness\", Symbol(\"k\"))", e)
  .run("pysetattr(self, \"l\", Symbol(\"l\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\")))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), (pyattr(self, \"q\") * pyattr(pyattr(self, \"N\"), \"x\")))", e)
  .run("spring <- LinearSpring(stiffness, pyattr(self, \"pathway\"), equilibrium_length)", e)
  expect_equal(.case("pyisinstance(spring, LinearSpring)", e), "True")
  expect_equal(.case("pyhasattr(spring, \"stiffness\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"stiffness\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"stiffness\")", e), "1")
  expect_equal(.case("pyhasattr(spring, \"pathway\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"pathway\"), LinearPathway)", e), "True")
  expect_equal(.case("pyattr(spring, \"pathway\")", e), "LinearPathway(pA, pB)")
  expect_equal(.case("pyhasattr(spring, \"equilibrium_length\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"equilibrium_length\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"equilibrium_length\")", e), "0")
  expect_equal(.case("pyhasattr(spring, \"force\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"force\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"force\")", e), "-sqrt(q(t)^2)")
})

