test_that("mechanics/tests/test_actuator.py::TestLinearDamper::test_to_loads matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"damping\", Symbol(\"c\"))", e)
  .run("pysetattr(self, \"l\", Symbol(\"l\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\")))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"dq\", dynamicsymbols(\"q\", 1))", e)
  .run("pysetattr(self, \"u\", dynamicsymbols(\"u\"))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), (pyattr(self, \"q\") * pyattr(pyattr(self, \"N\"), \"x\")))", e)
  .run("damper <- LinearDamper(pyattr(self, \"damping\"), pyattr(self, \"pathway\"))", e)
  .run("direction <- ((pypow(pyattr(self, \"q\"), 2) / pypow(pyattr(self, \"q\"), 2)) * pyattr(pyattr(self, \"N\"), \"x\"))", e)
  .run("pA_force <- ((pyattr(self, \"damping\") * pyattr(self, \"dq\")) * direction)", e)
  .run("pB_force <- (((-pyattr(self, \"damping\")) * pyattr(self, \"dq\")) * direction)", e)
  .run("expected <- list(Force(pyattr(self, \"pA\"), pA_force), Force(pyattr(self, \"pB\"), pB_force))", e)
  expect_equal(.case("pycall(damper, \"to_loads\")", e), "[(pA, c*Derivative(q(t), t)*N.x), (pB, - c*Derivative(q(t), t)*N.x)]")
})

test_that("mechanics/tests/test_actuator.py::TestForcedMassSpringDamperModel::test_force_acuator matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"m\", Symbol(\"m\"))", e)
  .run("pysetattr(self, \"k\", Symbol(\"k\"))", e)
  .run("pysetattr(self, \"c\", Symbol(\"c\"))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"dq\", dynamicsymbols(\"q\", 1))", e)
  .run("pysetattr(self, \"u\", dynamicsymbols(\"u\"))", e)
  .run("pysetattr(self, \"frame\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"origin\", PhysPoint(\"pO\"))", e)
  .run("pycall(pyattr(self, \"origin\"), \"set_vel\", pyattr(self, \"frame\"), 0)", e)
  .run("pysetattr(self, \"attachment\", PhysPoint(\"pA\"))", e)
  .run("pycall(pyattr(self, \"attachment\"), \"set_pos\", pyattr(self, \"origin\"), (pyattr(self, \"q\") * pyattr(pyattr(self, \"frame\"), \"x\")))", e)
  .run("pysetattr(self, \"mass\", Particle(\"mass\", pyattr(self, \"attachment\"), pyattr(self, \"m\")))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"origin\"), pyattr(self, \"attachment\")))", e)
  .run("pysetattr(self, \"kanes_method\", KanesMethod(pyattr(self, \"frame\"), q_ind = list(pyattr(self, \"q\")), u_ind = list(pyattr(self, \"u\")), kd_eqs = list((pyattr(self, \"dq\") - pyattr(self, \"u\")))))", e)
  .run("pysetattr(self, \"bodies\", list(pyattr(self, \"mass\")))", e)
  .run("pysetattr(self, \"mass_matrix\", Matrix(list(list(pyattr(self, \"m\")))))", e)
  .run("pysetattr(self, \"forcing\", Matrix(list(list(((pyattr(self, \"F\") - (pyattr(self, \"c\") * pyattr(self, \"u\"))) - (pyattr(self, \"k\") * pyattr(self, \"q\")))))))", e)
  .run("stiffness <- ((-pyattr(self, \"k\")) * pyattr(pyattr(self, \"pathway\"), \"length\"))", e)
  .run("spring <- ForceActuator(stiffness, pyattr(self, \"pathway\"))", e)
  .run("damping <- ((-pyattr(self, \"c\")) * pyattr(pyattr(self, \"pathway\"), \"extension_velocity\"))", e)
  .run("damper <- ForceActuator(damping, pyattr(self, \"pathway\"))", e)
  .run("loads <- c(list(tup(pyattr(self, \"attachment\"), (pyattr(self, \"F\") * pyattr(pyattr(self, \"frame\"), \"x\")))), pylist(pycall(spring, \"to_loads\")), pylist(pycall(damper, \"to_loads\")))", e)
  .run("pycall(pyattr(self, \"kanes_method\"), \"kanes_equations\", pyattr(self, \"bodies\"), loads)", e)
  expect_equal(.case("pyattr(pyattr(self, \"kanes_method\"), \"mass_matrix\")", e), "Matrix([[m]])")
  expect_equal(.case("pyattr(pyattr(self, \"kanes_method\"), \"forcing\")", e), "Matrix([[F - c*u(t) - k*q(t)]])")
})

