  .run("loads <- c(list(tup(pyattr(self, \"attachment\"), (pyattr(self, \"F\") * pyattr(pyattr(self, \"frame\"), \"x\")))), pylist(pycall(spring, \"to_loads\")), pylist(pycall(damper, \"to_loads\")))", e)
  .run("pycall(pyattr(self, \"kanes_method\"), \"kanes_equations\", pyattr(self, \"bodies\"), loads)", e)
  expect_equal(.case("pyattr(pyattr(self, \"kanes_method\"), \"mass_matrix\")", e), "Matrix([[m]])")
  expect_equal(.case("pyattr(pyattr(self, \"kanes_method\"), \"forcing\")", e), "Matrix([[F - c*u(t) - k*q(t)]])")
})

