test_that("mechanics/tests/test_actuator.py::TestTorqueActuator::test_at_pin_joint_constructor matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"torque\", Symbol(\"T\"))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"A\", ReferenceFrame(\"A\"))", e)
  .run("pysetattr(self, \"axis\", pyattr(pyattr(self, \"N\"), \"z\"))", e)
  .run("pysetattr(self, \"target\", RigidBody(\"target\", frame = pyattr(self, \"N\")))", e)
  .run("pysetattr(self, \"reaction\", RigidBody(\"reaction\", frame = pyattr(self, \"A\")))", e)
  .run("pin_joint <- PinJoint(\"pin\", pyattr(self, \"target\"), pyattr(self, \"reaction\"), coordinates = dynamicsymbols(\"q\"), speeds = dynamicsymbols(\"u\"), parent_interframe = pyattr(self, \"N\"), joint_axis = pyattr(self, \"axis\"))", e)
  .run("instance <- pyclassmethod(\"TorqueActuator\", \"at_pin_joint\")(pyattr(self, \"torque\"), pin_joint)", e)
  expect_equal(.case("pyisinstance(instance, TorqueActuator)", e), "True")
  expect_equal(.case("pyhasattr(instance, \"torque\")", e), "True")
  expect_equal(.case("pyattr(instance, \"torque\")", e), "T")
  expect_equal(.case("pyhasattr(instance, \"axis\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(instance, \"axis\"), PhysVector)", e), "True")
  expect_equal(.case("pyattr(instance, \"axis\")", e), "N.z")
  expect_equal(.case("pyhasattr(instance, \"target_frame\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(instance, \"target_frame\"), ReferenceFrame)", e), "True")
  expect_equal(.case("pyattr(instance, \"target_frame\")", e), "A")
  expect_equal(.case("pyhasattr(instance, \"reaction_frame\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(instance, \"reaction_frame\"), ReferenceFrame)", e), "True")
  expect_equal(.case("pyattr(instance, \"reaction_frame\")", e), "N")
})

