test_that("mechanics/tests/test_actuator.py::TestDuffingSpring::test_valid_constructor[0] matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("linear_stiffness <- 1", e)
  .run("expected_linear_stiffness <- S_One", e)
  .run("nonlinear_stiffness <- 1", e)
  .run("expected_nonlinear_stiffness <- S_One", e)
  .run("equilibrium_length <- 0", e)
  .run("expected_equilibrium_length <- S_Zero", e)
  .run("force <- ((-sqrt(pypow(dynamicsymbols(\"q\"), 2))) - pypow(sqrt(pypow(dynamicsymbols(\"q\"), 2)), 3))", e)
  .run("pysetattr(self, \"linear_stiffness\", Symbol(\"beta\"))", e)
  .run("pysetattr(self, \"nonlinear_stiffness\", Symbol(\"alpha\"))", e)
  .run("pysetattr(self, \"equilibrium_length\", Symbol(\"l\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\")))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), (pyattr(self, \"q\") * pyattr(pyattr(self, \"N\"), \"x\")))", e)
  .run("spring <- DuffingSpring(linear_stiffness, nonlinear_stiffness, pyattr(self, \"pathway\"), equilibrium_length)", e)
  expect_equal(.case("pyisinstance(spring, DuffingSpring)", e), "True")
  expect_equal(.case("pyhasattr(spring, \"linear_stiffness\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"linear_stiffness\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"linear_stiffness\")", e), "1")
  expect_equal(.case("pyhasattr(spring, \"nonlinear_stiffness\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"nonlinear_stiffness\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"nonlinear_stiffness\")", e), "1")
  expect_equal(.case("pyhasattr(spring, \"pathway\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"pathway\"), LinearPathway)", e), "True")
  expect_equal(.case("pyattr(spring, \"pathway\")", e), "LinearPathway(pA, pB)")
  expect_equal(.case("pyhasattr(spring, \"equilibrium_length\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"equilibrium_length\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"equilibrium_length\")", e), "0")
  expect_equal(.case("pyhasattr(spring, \"force\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(spring, \"force\"), ExprType)", e), "True")
  expect_equal(.case("pyattr(spring, \"force\")", e), "-(q(t)^2)^(3/2) - sqrt(q(t)^2)")
})

