test_that("mechanics/tests/test_actuator.py::TestCoulombKineticFriction::test_block_on_surface_default matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("\"A block sliding on a surface.\\\\n\\\\n        Notes\\\\n        =====\\\\n        This test validates the correctness of the CoulombKineticFriction by simulating\\\\n        a block sliding on a surface with the Coulomb kinetic friction force.\\\\n        The test covers scenarios with both positive and negative velocities.\\\\n\\\\n        \"", e)
  .run(".tmp <- pylist(pysymbols(\"m g mu_k mu_s v_s sigma F\", real = TRUE)); pysetattr(self, \"m\", .tmp[[1]]); pysetattr(self, \"g\", .tmp[[2]]); pysetattr(self, \"mu_k\", .tmp[[3]]); pysetattr(self, \"mu_s\", .tmp[[4]]); pysetattr(self, \"v_s\", .tmp[[5]]); pysetattr(self, \"sigma\", .tmp[[6]]); pysetattr(self, \"F\", .tmp[[7]])", e)
  .run("q <- dynamicsymbols(\"q\")", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway)", e)
  .run("expected_general <- list(Force(point = O, force = ((((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))), Force(point = P, force = (((((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, g*m*mu_k*q(t)*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t))/sqrt(q(t)^2)*N.x), (P, - g*m*mu_k*q(t)*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t))/sqrt(q(t)^2)*N.x)]")
  .run("q <- dynamicsymbols(\"q\", positive = TRUE)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway)", e)
  .run("expected_positive <- list(Force(point = O, force = ((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(pycall(q, \"diff\"))) * pyattr(N, \"x\"))), Force(point = P, force = (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(pycall(q, \"diff\"))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, g*m*mu_k*sign(Derivative(q(t), t))*N.x), (P, - g*m*mu_k*sign(Derivative(q(t), t))*N.x)]")
  .run("q <- dynamicsymbols(\"q\", positive = FALSE)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway)", e)
  .run("expected_negative <- list(Force(point = O, force = ((((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))), Force(point = P, force = (((((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, g*m*mu_k*q(t)*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t))/sqrt(q(t)^2)*N.x), (P, - g*m*mu_k*q(t)*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t))/sqrt(q(t)^2)*N.x)]")
})

test_that("mechanics/tests/test_actuator.py::TestCoulombKineticFriction::test_block_on_surface_viscous matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("\"A block sliding on a surface.\\\\n\\\\n        Notes\\\\n        =====\\\\n        This test validates the correctness of the CoulombKineticFriction by simulating\\\\n        a block sliding on a surface with the Coulomb kinetic friction force.\\\\n        The test covers scenarios with both positive and negative velocities.\\\\n\\\\n        \"", e)
  .run(".tmp <- pylist(pysymbols(\"m g mu_k mu_s v_s sigma F\", real = TRUE)); pysetattr(self, \"m\", .tmp[[1]]); pysetattr(self, \"g\", .tmp[[2]]); pysetattr(self, \"mu_k\", .tmp[[3]]); pysetattr(self, \"mu_s\", .tmp[[4]]); pysetattr(self, \"v_s\", .tmp[[5]]); pysetattr(self, \"sigma\", .tmp[[6]]); pysetattr(self, \"F\", .tmp[[7]])", e)
  .run("q <- dynamicsymbols(\"q\")", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway, sigma = pyattr(self, \"sigma\"))", e)
  .run("expected_general <- list(Force(point = O, force = (((((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) + (((pyattr(self, \"sigma\") * sqrt(pypow(q, 2))) * pycall(q, \"diff\")) / q)) * q) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))), Force(point = P, force = ((((((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) - (((pyattr(self, \"sigma\") * sqrt(pypow(q, 2))) * pycall(q, \"diff\")) / q)) * q) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, (g*m*mu_k*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t)) + sigma*sqrt(q(t)^2)*Derivative(q(t), t)/q(t))*q(t)/sqrt(q(t)^2)*N.x), (P, (-g*m*mu_k*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t)) - sigma*sqrt(q(t)^2)*Derivative(q(t), t)/q(t))*q(t)/sqrt(q(t)^2)*N.x)]")
  .run("q <- dynamicsymbols(\"q\", positive = TRUE)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway, sigma = pyattr(self, \"sigma\"))", e)
  .run("expected_positive <- list(Force(point = O, force = (((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(pycall(q, \"diff\"))) + (pyattr(self, \"sigma\") * pycall(q, \"diff\"))) * pyattr(N, \"x\"))), Force(point = P, force = ((((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(pycall(q, \"diff\"))) - (pyattr(self, \"sigma\") * pycall(q, \"diff\"))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, (g*m*mu_k*sign(Derivative(q(t), t)) + sigma*Derivative(q(t), t))*N.x), (P, (-g*m*mu_k*sign(Derivative(q(t), t)) - sigma*Derivative(q(t), t))*N.x)]")
  .run("q <- dynamicsymbols(\"q\", positive = FALSE)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway, sigma = pyattr(self, \"sigma\"))", e)
  .run("expected_negative <- list(Force(point = O, force = (((((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) + (((pyattr(self, \"sigma\") * sqrt(pypow(q, 2))) * pycall(q, \"diff\")) / q)) * q) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))), Force(point = P, force = ((((((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) - (((pyattr(self, \"sigma\") * sqrt(pypow(q, 2))) * pycall(q, \"diff\")) / q)) * q) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, (g*m*mu_k*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t)) + sigma*sqrt(q(t)^2)*Derivative(q(t), t)/q(t))*q(t)/sqrt(q(t)^2)*N.x), (P, (-g*m*mu_k*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t)) - sigma*sqrt(q(t)^2)*Derivative(q(t), t)/q(t))*q(t)/sqrt(q(t)^2)*N.x)]")
})

test_that("mechanics/tests/test_actuator.py::TestCoulombKineticFriction::test_block_on_surface_stribeck matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("\"A block sliding on a surface.\\\\n\\\\n        Notes\\\\n        =====\\\\n        This test validates the correctness of the CoulombKineticFriction by simulating\\\\n        a block sliding on a surface with the Coulomb kinetic friction force.\\\\n        The test covers scenarios with both positive and negative velocities.\\\\n\\\\n        \"", e)
  .run(".tmp <- pylist(pysymbols(\"m g mu_k mu_s v_s sigma F\", real = TRUE)); pysetattr(self, \"m\", .tmp[[1]]); pysetattr(self, \"g\", .tmp[[2]]); pysetattr(self, \"mu_k\", .tmp[[3]]); pysetattr(self, \"mu_s\", .tmp[[4]]); pysetattr(self, \"v_s\", .tmp[[5]]); pysetattr(self, \"sigma\", .tmp[[6]]); pysetattr(self, \"F\", .tmp[[7]])", e)
  .run("q <- dynamicsymbols(\"q\")", e)
  .run("N <- ReferenceFrame(\"N\")", e)
