  .run("expected_general <- list(Force(point = O, force = (((((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + ((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_s\"))) * exp(((-pypow(pycall(q, \"diff\"), 2)) / pypow(pyattr(self, \"v_s\"), 2))))) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))), Force(point = P, force = (((((-(((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + ((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_s\"))) * exp(((-pypow(pycall(q, \"diff\"), 2)) / pypow(pyattr(self, \"v_s\"), 2)))))) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))))", e)
