  .run("q <- dynamicsymbols(\"q\", positive = TRUE)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (q * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway, v_s = pyattr(self, \"v_s\"), mu_s = pyattr(self, \"mu_s\"))", e)
  .run("expected_positive <- list(Force(point = O, force = (((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + ((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_s\"))) * exp(((-pypow(pycall(q, \"diff\"), 2)) / pypow(pyattr(self, \"v_s\"), 2))))) * sign(pycall(q, \"diff\"))) * pyattr(N, \"x\"))), Force(point = P, force = (((-(((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + ((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_s\"))) * exp(((-pypow(pycall(q, \"diff\"), 2)) / pypow(pyattr(self, \"v_s\"), 2)))))) * sign(pycall(q, \"diff\"))) * pyattr(N, \"x\"))))", e)
