  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"set_vel\", N, (pycall(q, \"diff\") * pyattr(N, \"x\")))", e)
  .run("pathway <- LinearPathway(O, P)", e)
  .run("friction <- CoulombKineticFriction(pyattr(self, \"mu_k\"), (pyattr(self, \"m\") * pyattr(self, \"g\")), pathway, v_s = pyattr(self, \"v_s\"), mu_s = pyattr(self, \"mu_s\"))", e)
  .run("expected_negative <- list(Force(point = O, force = (((((((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + ((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_s\"))) * exp(((-pypow(pycall(q, \"diff\"), 2)) / pypow(pyattr(self, \"v_s\"), 2))))) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))), Force(point = P, force = (((((-(((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + (((((-pyattr(self, \"g\")) * pyattr(self, \"m\")) * pyattr(self, \"mu_k\")) + ((pyattr(self, \"g\") * pyattr(self, \"m\")) * pyattr(self, \"mu_s\"))) * exp(((-pypow(pycall(q, \"diff\"), 2)) / pypow(pyattr(self, \"v_s\"), 2)))))) * q) * sign(((sqrt(pypow(q, 2)) * pycall(q, \"diff\")) / q))) / sqrt(pypow(q, 2))) * pyattr(N, \"x\"))))", e)
  expect_equal(.case("pycall(friction, \"to_loads\")", e), "[(O, (g*m*mu_k + (-g*m*mu_k + g*m*mu_s)*exp(-Derivative(q(t), t)^2/v_s^2))*q(t)*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t))/sqrt(q(t)^2)*N.x), (P, - (g*m*mu_k + (-g*m*mu_k + g*m*mu_s)*exp(-Derivative(q(t), t)^2/v_s^2))*q(t)*sign(sqrt(q(t)^2)*Derivative(q(t), t)/q(t))/sqrt(q(t)^2)*N.x)]")
})

