test_that("mechanics/tests/test_body.py::test_default matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("body <- Body(\"body\")", e)
  expect_equal(.case("pyattr(body, \"name\")", e), "body")
  expect_equal(.case("pyattr(body, \"loads\")", e), "[]")
  .run("point <- PhysPoint(\"body_masscenter\")", e)
  .run("pycall(point, \"set_vel\", pyattr(body, \"frame\"), 0)", e)
  .run("com <- pyattr(body, \"masscenter\")", e)
  .run("frame <- pyattr(body, \"frame\")", e)
  expect_equal(.case("pycall(com, \"vel\", frame)", e), "0")
  expect_equal(.case("pyattr(body, \"mass\")", e), "body_mass")
  .run(".tmp <- pylist(pysymbols(\"body_ixx body_iyy body_izz\")); ixx <- .tmp[[1]]; iyy <- .tmp[[2]]; izz <- .tmp[[3]]", e)
  .run(".tmp <- pylist(pysymbols(\"body_ixy body_iyz body_izx\")); ixy <- .tmp[[1]]; iyz <- .tmp[[2]]; izx <- .tmp[[3]]", e)
  expect_equal(.case("pyattr(body, \"inertia\")", e), "(body_ixx*(body_frame.x|body_frame.x) + body_ixy*(body_frame.x|body_frame.y) + body_izx*(body_frame.x|body_frame.z) + body_ixy*(body_frame.y|body_frame.x) + body_iyy*(body_frame.y|body_frame.y) + body_iyz*(body_frame.y|body_frame.z) + body_izx*(body_frame.z|body_frame.x) + body_iyz*(body_frame.z|body_frame.y) + body_izz*(body_frame.z|body_frame.z), body_masscenter)")
})

test_that("mechanics/tests/test_body.py::test_custom_rigid_body matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("rigidbody_masscenter <- PhysPoint(\"rigidbody_masscenter\")", e)
  .run("rigidbody_mass <- Symbol(\"rigidbody_mass\")", e)
  .run("rigidbody_frame <- ReferenceFrame(\"rigidbody_frame\")", e)
  .run("body_inertia <- inertia(rigidbody_frame, 1, 0, 0)", e)
  .run("rigid_body <- Body(\"rigidbody_body\", rigidbody_masscenter, rigidbody_mass, rigidbody_frame, body_inertia)", e)
  .run("com <- pyattr(rigid_body, \"masscenter\")", e)
  .run("frame <- pyattr(rigid_body, \"frame\")", e)
  .run("pycall(rigidbody_masscenter, \"set_vel\", rigidbody_frame, 0)", e)
  expect_equal(.case("pycall(com, \"vel\", frame)", e), "0")
  expect_equal(.case("pycall(com, \"pos_from\", com)", e), "0")
  expect_equal(.case("pyattr(rigid_body, \"mass\")", e), "rigidbody_mass")
  expect_equal(.case("pyattr(rigid_body, \"inertia\")", e), "((rigidbody_frame.x|rigidbody_frame.x), rigidbody_masscenter)")
  expect_equal(.case("pyattr(rigid_body, \"is_rigidbody\")", e), "True")
  expect_equal(.case("pyhasattr(rigid_body, \"masscenter\")", e), "True")
  expect_equal(.case("pyhasattr(rigid_body, \"mass\")", e), "True")
  expect_equal(.case("pyhasattr(rigid_body, \"frame\")", e), "True")
  expect_equal(.case("pyhasattr(rigid_body, \"inertia\")", e), "True")
})

test_that("mechanics/tests/test_body.py::test_particle_body matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("particle_masscenter <- PhysPoint(\"particle_masscenter\")", e)
  .run("particle_mass <- Symbol(\"particle_mass\")", e)
  .run("particle_frame <- ReferenceFrame(\"particle_frame\")", e)
  .run("particle_body <- Body(\"particle_body\", particle_masscenter, particle_mass, particle_frame)", e)
  .run("com <- pyattr(particle_body, \"masscenter\")", e)
  .run("frame <- pyattr(particle_body, \"frame\")", e)
  .run("pycall(particle_masscenter, \"set_vel\", particle_frame, 0)", e)
  expect_equal(.case("pycall(com, \"vel\", frame)", e), "0")
  expect_equal(.case("pycall(com, \"pos_from\", com)", e), "0")
  expect_equal(.case("pyattr(particle_body, \"mass\")", e), "particle_mass")
  expect_equal(.case("(!pybool(pyhasattr(particle_body, \"_inertia\")))", e), "True")
  expect_equal(.case("pyhasattr(particle_body, \"frame\")", e), "True")
  expect_equal(.case("pyhasattr(particle_body, \"masscenter\")", e), "True")
  expect_equal(.case("pyhasattr(particle_body, \"mass\")", e), "True")
  expect_equal(.case("pyattr(particle_body, \"inertia\")", e), "(0, particle_masscenter)")
  expect_equal(.case("pyattr(particle_body, \"central_inertia\")", e), "0")
  expect_equal(.case("(!pybool(pyattr(particle_body, \"is_rigidbody\")))", e), "True")
  .run("pysetattr(particle_body, \"central_inertia\", inertia(particle_frame, 1, 1, 1))", e)
  expect_equal(.case("pyattr(particle_body, \"central_inertia\")", e), "(particle_frame.x|particle_frame.x) + (particle_frame.y|particle_frame.y) + (particle_frame.z|particle_frame.z)")
  expect_equal(.case("pyattr(particle_body, \"is_rigidbody\")", e), "True")
  .run("particle_body <- Body(\"particle_body\", mass = particle_mass)", e)
  expect_equal(.case("(!pybool(pyattr(particle_body, \"is_rigidbody\")))", e), "True")
  .run("point <- pycall(pyattr(particle_body, \"masscenter\"), \"locatenew\", \"point\", pyattr(particle_body, \"x\"))", e)
  .run("point_inertia <- (particle_mass * inertia(pyattr(particle_body, \"frame\"), 0, 1, 1))", e)
  .run("pysetattr(particle_body, \"inertia\", tup(point_inertia, point))", e)
  expect_equal(.case("pyattr(particle_body, \"inertia\")", e), "(particle_mass*(particle_body_frame.y|particle_body_frame.y) + particle_mass*(particle_body_frame.z|particle_body_frame.z), point)")
  expect_equal(.case("pyattr(particle_body, \"central_inertia\")", e), "0")
  expect_equal(.case("pyattr(particle_body, \"is_rigidbody\")", e), "True")
})

test_that("mechanics/tests/test_body.py::test_particle_body_add_force matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("particle_masscenter <- PhysPoint(\"particle_masscenter\")", e)
  .run("particle_mass <- Symbol(\"particle_mass\")", e)
  .run("particle_frame <- ReferenceFrame(\"particle_frame\")", e)
  .run("particle_body <- Body(\"particle_body\", particle_masscenter, particle_mass, particle_frame)", e)
  .run("a <- Symbol(\"a\")", e)
  .run("force_vector <- (a * pyattr(pyattr(particle_body, \"frame\"), \"x\"))", e)
  .run("pycall(particle_body, \"apply_force\", force_vector, pyattr(particle_body, \"masscenter\"))", e)
  expect_equal(.case("length(pyattr(particle_body, \"loads\"))", e), "1")
  .run("point <- pycall(pyattr(particle_body, \"masscenter\"), \"locatenew\", (pyattr(particle_body, \"_name\") + \"_point0\"), 0)", e)
  .run("pycall(point, \"set_vel\", pyattr(particle_body, \"frame\"), 0)", e)
  .run("force_point <- pyget(pyget(pyattr(particle_body, \"loads\"), 0), 0)", e)
  .run("frame <- pyattr(particle_body, \"frame\")", e)
  expect_equal(.case("pycall(force_point, \"vel\", frame)", e), "0")
  expect_equal(.case("pycall(force_point, \"pos_from\", force_point)", e), "0")
  expect_equal(.case("pyget(pyget(pyattr(particle_body, \"loads\"), 0), 1)", e), "a*particle_frame.x")
})

test_that("mechanics/tests/test_body.py::test_body_add_force matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("rigidbody_masscenter <- PhysPoint(\"rigidbody_masscenter\")", e)
  .run("rigidbody_mass <- Symbol(\"rigidbody_mass\")", e)
  .run("rigidbody_frame <- ReferenceFrame(\"rigidbody_frame\")", e)
  .run("body_inertia <- inertia(rigidbody_frame, 1, 0, 0)", e)
  .run("rigid_body <- Body(\"rigidbody_body\", rigidbody_masscenter, rigidbody_mass, rigidbody_frame, body_inertia)", e)
  .run("l <- Symbol(\"l\")", e)
  .run("Fa <- Symbol(\"Fa\")", e)
  .run("point <- pycall(pyattr(rigid_body, \"masscenter\"), \"locatenew\", \"rigidbody_body_point0\", (l * pyattr(pyattr(rigid_body, \"frame\"), \"x\")))", e)
  .run("pycall(point, \"set_vel\", pyattr(rigid_body, \"frame\"), 0)", e)
  .run("force_vector <- (Fa * pyattr(pyattr(rigid_body, \"frame\"), \"z\"))", e)
  .run("pycall(rigid_body, \"apply_force\", force_vector, point)", e)
  expect_equal(.case("length(pyattr(rigid_body, \"loads\"))", e), "1")
  .run("force_point <- pyget(pyget(pyattr(rigid_body, \"loads\"), 0), 0)", e)
  .run("frame <- pyattr(rigid_body, \"frame\")", e)
  expect_equal(.case("pycall(force_point, \"vel\", frame)", e), "0")
  expect_equal(.case("pycall(force_point, \"pos_from\", force_point)", e), "0")
  expect_equal(.case("pyget(pyget(pyattr(rigid_body, \"loads\"), 0), 1)", e), "Fa*rigidbody_frame.z")
  .run("pycall(rigid_body, \"apply_force\", force_vector)", e)
  expect_equal(.case("length(pyattr(rigid_body, \"loads\"))", e), "2")
  expect_equal(.case("pyget(pyget(pyattr(rigid_body, \"loads\"), 1), 1)", e), "Fa*rigidbody_frame.z")
  expect_equal(.case("pycall(rigid_body, \"apply_force\", force_vector, 0)", e), "ERR TypeError: Force must be applied to a point on the body.")
  expect_equal(.case("pycall(rigid_body, \"apply_force\", 0)", e), "ERR TypeError: Force must be a vector.")
})

