test_that("mechanics/tests/test_body.py::test_apply_force matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"f g\")); f <- .tmp[[1]]; g <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q x v1 v2\")); q <- .tmp[[1]]; x <- .tmp[[2]]; v1 <- .tmp[[3]]; v2 <- .tmp[[4]]", e)
  .run("P1 <- PhysPoint(\"P1\")", e)
  .run("P2 <- PhysPoint(\"P2\")", e)
  .run("B1 <- Body(\"B1\")", e)
  .run("B2 <- Body(\"B2\")", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("pycall(P1, \"set_vel\", pyattr(B1, \"frame\"), (v1 * pyattr(B1, \"x\")))", e)
  .run("pycall(P2, \"set_vel\", pyattr(B2, \"frame\"), (v2 * pyattr(B2, \"x\")))", e)
  .run("force <- ((f * q) * pyattr(N, \"z\"))", e)
  .run("pycall(B1, \"apply_force\", force, P1, B2, P2)", e)
  expect_equal(.case("pyattr(B1, \"loads\")", e), "[(P1, f*q(t)*N.z)]")
  expect_equal(.case("pyattr(B2, \"loads\")", e), "[(P2, - f*q(t)*N.z)]")
  .run("g1 <- ((pyattr(B1, \"mass\") * g) * pyattr(N, \"y\"))", e)
  .run("g2 <- ((pyattr(B2, \"mass\") * g) * pyattr(N, \"y\"))", e)
  .run("pycall(B1, \"apply_force\", g1)", e)
  .run("pycall(B2, \"apply_force\", g2)", e)
  expect_equal(.case("pyattr(B1, \"loads\")", e), "[(P1, f*q(t)*N.z), (B1_masscenter, B1_mass*g*N.y)]")
  expect_equal(.case("pyattr(B2, \"loads\")", e), "[(P2, - f*q(t)*N.z), (B2_masscenter, B2_mass*g*N.y)]")
  .run("force2 <- (x * pyattr(N, \"x\"))", e)
  .run("pycall(B1, \"apply_force\", force2, reaction_body = B2)", e)
  expect_equal(.case("pyattr(B1, \"loads\")", e), "[(P1, f*q(t)*N.z), (B1_masscenter, x(t)*N.x + B1_mass*g*N.y)]")
  expect_equal(.case("pyattr(B2, \"loads\")", e), "[(P2, - f*q(t)*N.z), (B2_masscenter, - x(t)*N.x + B2_mass*g*N.y)]")
})

