test_that("mechanics/tests/test_body.py::test_apply_loads_on_multi_degree_freedom_holonomic_system matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("\"Example based on: https://pydy.readthedocs.io/en/latest/examples/multidof-holonomic.html\"", e)
  .run("W <- Body(\"W\")", e)
  .run("B <- Body(\"B\")", e)
  .run("P <- Body(\"P\")", e)
  .run("b <- Body(\"b\")", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"k c g kT\")); k <- .tmp[[1]]; c <- .tmp[[2]]; g <- .tmp[[3]]; kT <- .tmp[[4]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"F T\")); `F` <- .tmp[[1]]; `T` <- .tmp[[2]]", e)
  .run("pycall(B, \"apply_force\", (`F` * pyattr(W, \"x\")))", e)
  .run("pycall(W, \"apply_force\", ((k * q1) * pyattr(W, \"x\")), reaction_body = B)", e)
  .run("pycall(W, \"apply_force\", ((c * pycall(q1, \"diff\")) * pyattr(W, \"x\")), reaction_body = B)", e)
  .run("pycall(P, \"apply_force\", ((pyattr(P, \"mass\") * g) * pyattr(W, \"y\")))", e)
  .run("pycall(b, \"apply_force\", ((pyattr(b, \"mass\") * g) * pyattr(W, \"y\")))", e)
  .run("pycall(P, \"apply_torque\", ((kT * q2) * pyattr(W, \"z\")), reaction_body = b)", e)
  .run("pycall(P, \"apply_torque\", (`T` * pyattr(W, \"z\")))", e)
  expect_equal(.case("pyattr(B, \"loads\")", e), "[(B_masscenter, (-c*Derivative(q1(t), t) - k*q1(t) + F(t))*W_frame.x)]")
  expect_equal(.case("pyattr(P, \"loads\")", e), "[(P_masscenter, P_mass*g*W_frame.y), (P_frame, (kT*q2(t) + T(t))*W_frame.z)]")
  expect_equal(.case("pyattr(b, \"loads\")", e), "[(b_masscenter, b_mass*g*W_frame.y), (b_frame, - kT*q2(t)*W_frame.z)]")
  expect_equal(.case("pyattr(W, \"loads\")", e), "[(W_masscenter, (c*Derivative(q1(t), t) + k*q1(t))*W_frame.x)]")
})

test_that("mechanics/tests/test_body.py::test_parallel_axis matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("N <- ReferenceFrame(\"N\")", e)
  .run(".tmp <- pylist(pysymbols(\"m, I_x, I_y, I_z, a, b\")); m <- .tmp[[1]]; Ix <- .tmp[[2]]; Iy <- .tmp[[3]]; Iz <- .tmp[[4]]; a <- .tmp[[5]]; b <- .tmp[[6]]", e)
  .run("Io <- inertia(N, Ix, Iy, Iz)", e)
  .run("o <- PhysPoint(\"o\")", e)
  .run("p <- pycall(o, \"locatenew\", \"p\", ((a * pyattr(N, \"x\")) + (b * pyattr(N, \"y\"))))", e)
  .run("R <- Body(\"R\", masscenter = o, frame = N, mass = m, central_inertia = Io)", e)
  .run("Ip <- pycall(R, \"parallel_axis\", p)", e)
  .run("Ip_expected <- inertia(N, (Ix + (m * pypow(b, 2))), (Iy + (m * pypow(a, 2))), (Iz + (m * (pypow(a, 2) + pypow(b, 2)))), ixy = (((-m) * a) * b))", e)
  expect_equal(.case("Ip", e), "(I_x + b^2*m)*(N.x|N.x) + (I_y + a^2*m)*(N.y|N.y) + (I_z + m*(a^2 + b^2))*(N.z|N.z) - a*b*m*(N.x|N.y) - a*b*m*(N.y|N.x)")
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("pycall(A, \"orient_axis\", N, pyattr(N, \"z\"), 1)", e)
  expect_equal(.case("pysimplify(pycall((pycall(R, \"parallel_axis\", p, A) - Ip_expected), \"to_matrix\", A))", e), "Matrix([[0, 0, 0], [0, 0, 0], [0, 0, 0]])")
  .run("o <- PhysPoint(\"o\")", e)
  .run("p <- pycall(o, \"locatenew\", \"p\", ((a * pyattr(N, \"x\")) + (b * pyattr(N, \"y\"))))", e)
  .run("P <- Body(\"P\", masscenter = o, mass = m, frame = N)", e)
  .run("Ip <- pycall(P, \"parallel_axis\", p, N)", e)
  .run("Ip_expected <- inertia(N, (m * pypow(b, 2)), (m * pypow(a, 2)), (m * (pypow(a, 2) + pypow(b, 2))), ixy = (((-m) * a) * b))", e)
  expect_equal(.case("(!pybool(pyattr(P, \"is_rigidbody\")))", e), "True")
  expect_equal(.case("Ip", e), "b^2*m*(N.x|N.x) + a^2*m*(N.y|N.y) + m*(a^2 + b^2)*(N.z|N.z) - a*b*m*(N.x|N.y) - a*b*m*(N.y|N.x)")
})

