test_that("mechanics/tests/test_functions.py::test_linear_momentum matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("Ac <- PhysPoint(\"Ac\")", e)
  .run("pycall(Ac, \"set_vel\", N, (25 * pyattr(N, \"y\")))", e)
  .run("I <- outer_sym(pyattr(N, \"x\"), pyattr(N, \"x\"))", e)
  .run("A <- RigidBody(\"A\", Ac, N, 20, tup(I, Ac))", e)
  .run("P <- PhysPoint(\"P\")", e)
  .run("Pa <- Particle(\"Pa\", P, 1)", e)
  .run("pycall(pyattr(Pa, \"point\"), \"set_vel\", N, (10 * pyattr(N, \"x\")))", e)
  expect_equal(.case("linear_momentum(A, A, Pa)", e), "ERR TypeError: Please specify a valid ReferenceFrame")
  expect_equal(.case("linear_momentum(N, N, Pa)", e), "ERR TypeError: *body must have only Particle or RigidBody")
  expect_equal(.case("linear_momentum(N, A, Pa)", e), "10*N.x + 500*N.y")
})

test_that("mechanics/tests/test_functions.py::test_angular_momentum_and_linear_momentum matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("\"A rod with length 2l, centroidal inertia I, and mass M along with a\\\\n    particle of mass m fixed to the end of the rod rotate with an angular rate\\\\n    of omega about point O which is fixed to the non-particle end of the rod.\\\\n    The rod's reference frame is A and the inertial frame is N.\"", e)
  .run(".tmp <- pylist(pysymbols(\"m, M, l, I\")); m <- .tmp[[1]]; M <- .tmp[[2]]; l <- .tmp[[3]]; I <- .tmp[[4]]", e)
  .run("omega <- dynamicsymbols(\"omega\")", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("a <- ReferenceFrame(\"a\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("Ac <- pycall(O, \"locatenew\", \"Ac\", (l * pyattr(N, \"x\")))", e)
  .run("P <- pycall(Ac, \"locatenew\", \"P\", (l * pyattr(N, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, (0 * pyattr(N, \"x\")))", e)
  .run("pycall(a, \"set_ang_vel\", N, (omega * pyattr(N, \"z\")))", e)
  .run("pycall(Ac, \"v2pt_theory\", O, N, a)", e)
  .run("pycall(P, \"v2pt_theory\", O, N, a)", e)
  .run("Pa <- Particle(\"Pa\", P, m)", e)
  .run("A <- RigidBody(\"A\", Ac, a, M, tup((I * outer_sym(pyattr(N, \"z\"), pyattr(N, \"z\"))), Ac))", e)
  .run("expected <- (((((2 * m) * omega) * l) * pyattr(N, \"y\")) + (((M * l) * omega) * pyattr(N, \"y\")))", e)
  expect_equal(.case("linear_momentum(N, A, Pa)", e), "(M*l*omega(t) + 2*l*m*omega(t))*N.y")
  expect_equal(.case("angular_momentum(N, N, A, Pa)", e), "ERR TypeError: Please specify a valid Point")
  expect_equal(.case("angular_momentum(O, O, A, Pa)", e), "ERR TypeError: Please enter a valid ReferenceFrame")
  expect_equal(.case("angular_momentum(O, N, O, Pa)", e), "ERR TypeError: *body must have only Particle or RigidBody")
  .run("expected <- ((((I + (M * pypow(l, 2))) + ((4 * m) * pypow(l, 2))) * omega) * pyattr(N, \"z\"))", e)
  expect_equal(.case("angular_momentum(O, N, A, Pa)", e), "(I*omega(t) + M*l^2*omega(t) + 4*l^2*m*omega(t))*N.z")
})

