test_that("mechanics/tests/test_functions.py::test_msubs matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"a, b\")); a <- .tmp[[1]]; b <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"x, y, z\")); x <- .tmp[[1]]; y <- .tmp[[2]]; z <- .tmp[[3]]", e)
  .run("expr <- Matrix(list(list(((a * x) + b), ((x * pycall(y, \"diff\")) + y)), list(pycall(pycall(x, \"diff\"), \"diff\"), (z + sin(pycall(z, \"diff\"))))))", e)
  .run("sol <- Matrix(list(list((a + b), y), list(pycall(pycall(x, \"diff\"), \"diff\"), 1)))", e)
  .run("sd <- pydict(list(x, z, pycall(z, \"diff\"), pycall(y, \"diff\")), list(1, 1, 0, 0))", e)
  expect_equal(.case("msubs(expr, sd)", e), "Matrix([[a + b, y(t)], [Derivative(x(t), (t, 2)), 1]])")
  .run("expr <- ((cos((x + y)) * tan((x + y))) + (b * pycall(x, \"diff\")))", e)
  .run("sd <- pydict(list(x, y, pycall(x, \"diff\")), list(0, (S_Pi / 2), 1))", e)
  expect_equal(.case("msubs(expr, sd, smart = TRUE)", e), "b + 1")
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("v <- ((x * pyattr(N, \"x\")) + (y * pyattr(N, \"y\")))", e)
  .run("d <- ((x * (pyattr(N, \"x\") | pyattr(N, \"x\"))) + (y * (pyattr(N, \"y\") | pyattr(N, \"y\"))))", e)
  .run("v_sol <- (1 * pyattr(N, \"y\"))", e)
  .run("d_sol <- (1 * (pyattr(N, \"y\") | pyattr(N, \"y\")))", e)
  .run("sd <- pydict(list(x, y), list(0, 1))", e)
  expect_equal(.case("msubs(v, sd)", e), "N.y")
  expect_equal(.case("msubs(d, sd)", e), "(N.y|N.y)")
})

test_that("mechanics/tests/test_functions.py::test_find_dynamicsymbols matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"a, b\")); a <- .tmp[[1]]; b <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"x, y, z\")); x <- .tmp[[1]]; y <- .tmp[[2]]; z <- .tmp[[3]]", e)
  .run("expr <- Matrix(list(list(((a * x) + b), ((x * pycall(y, \"diff\")) + y)), list(pycall(pycall(x, \"diff\"), \"diff\"), (z + sin(pycall(z, \"diff\"))))))", e)
  .run("sol <- pyset(list(x, pycall(y, \"diff\"), y, pycall(pycall(x, \"diff\"), \"diff\"), z, pycall(z, \"diff\")))", e)
  expect_equal(.case("find_dynamicsymbols(expr)", e), "{Derivative(x(t), (t, 2)), Derivative(y(t), t), Derivative(z(t), t), x(t), y(t), z(t)}")
  .run("exclude_list <- list(x, y, z)", e)
  .run("sol <- pyset(list(pycall(y, \"diff\"), pycall(pycall(x, \"diff\"), \"diff\"), pycall(z, \"diff\")))", e)
  expect_equal(.case("find_dynamicsymbols(expr, exclude = exclude_list)", e), "{Derivative(x(t), (t, 2)), Derivative(y(t), t), Derivative(z(t), t)}")
  .run(".tmp <- pylist(dynamicsymbols(\"d, e, f\")); d <- .tmp[[1]]; e <- .tmp[[2]]; f <- .tmp[[3]]", e)
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("v <- (((d * pyattr(A, \"x\")) + (e * pyattr(A, \"y\"))) + (f * pyattr(A, \"z\")))", e)
  .run("sol <- pyset(list(d, e, f))", e)
  expect_equal(.case("find_dynamicsymbols(v, reference_frame = A)", e), "{d(t), e(t), f(t)}")
  expect_equal(.case("find_dynamicsymbols(v)", e), "ERR ValueError: You must provide reference_frame when passing a vector expression, got None.")
})

test_that("mechanics/tests/test_functions.py::test_center_of_mass matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("a <- ReferenceFrame(\"a\")", e)
  .run("m <- pysymbols(\"m\", real = TRUE)", e)
  .run("p1 <- Particle(\"p1\", PhysPoint(\"p1_pt\"), S_One)", e)
  .run("p2 <- Particle(\"p2\", PhysPoint(\"p2_pt\"), S(2))", e)
  .run("p3 <- Particle(\"p3\", PhysPoint(\"p3_pt\"), S(3))", e)
  .run("p4 <- Particle(\"p4\", PhysPoint(\"p4_pt\"), m)", e)
  .run("b_f <- ReferenceFrame(\"b_f\")", e)
  .run("b_cm <- PhysPoint(\"b_cm\")", e)
  .run("mb <- pysymbols(\"mb\")", e)
  .run("b <- RigidBody(\"b\", b_cm, b_f, mb, tup(outer_sym(pyattr(b_f, \"x\"), pyattr(b_f, \"x\")), b_cm))", e)
  .run("pycall(pyattr(p2, \"point\"), \"set_pos\", pyattr(p1, \"point\"), pyattr(a, \"x\"))", e)
  .run("pycall(pyattr(p3, \"point\"), \"set_pos\", pyattr(p1, \"point\"), (pyattr(a, \"x\") + pyattr(a, \"y\")))", e)
  .run("pycall(pyattr(p4, \"point\"), \"set_pos\", pyattr(p1, \"point\"), pyattr(a, \"y\"))", e)
  .run("pycall(pyattr(b, \"masscenter\"), \"set_pos\", pyattr(p1, \"point\"), (pyattr(a, \"y\") + pyattr(a, \"z\")))", e)
  .run("point_o <- PhysPoint(\"o\")", e)
  .run("pycall(point_o, \"set_pos\", pyattr(p1, \"point\"), center_of_mass(pyattr(p1, \"point\"), p1, p2, p3, p4, b))", e)
  .run("expr <- ((((5 / ((m + mb) + 6)) * pyattr(a, \"x\")) + ((((m + mb) + 3) / ((m + mb) + 6)) * pyattr(a, \"y\"))) + ((mb / ((m + mb) + 6)) * pyattr(a, \"z\")))", e)
  expect_equal(.case("(pycall(point_o, \"pos_from\", pyattr(p1, \"point\")) - expr)", e), "0")
})

test_that("mechanics/tests/test_functions.py::test_validate_coordinates matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1:4 u1:4 ua1:4\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; u1 <- .tmp[[4]]; u2 <- .tmp[[5]]; u3 <- .tmp[[6]]; ua1 <- .tmp[[7]]; ua2 <- .tmp[[8]]; ua3 <- .tmp[[9]]", e)
  .run(".tmp <- pylist(pysymbols(\"s1:4\")); s1 <- .tmp[[1]]; s2 <- .tmp[[2]]; s3 <- .tmp[[3]]", e)
  .run("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u3), u_auxiliary = list(ua1, ua2, ua3))", e)
  .run("`_validate_coordinates`(list(q1, q2))", e)
  .run("`_validate_coordinates`(list(q1, q2), list(u1))", e)
  .run("`_validate_coordinates`(speeds = list(u1, u2))", e)
  .run("`_validate_coordinates`(list(q1, q2, q2), list(u1, u2, u3), check_duplicates = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(list(q1, q2, q2), list(u1, u2, u3))", e), "ERR ValueError: The generalized coordinates {q2(t)} are duplicated, all generalized coordinates should be unique.")
  .run("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u2), check_duplicates = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u2), check_duplicates = TRUE)", e), "ERR ValueError: The generalized speeds {u2(t)} are duplicated, all generalized speeds should be unique.")
  expect_equal(.case("`_validate_coordinates`(list(q1, q2, q3), list(q1, u2, u3), check_duplicates = TRUE)", e), "ERR ValueError: {q1(t)} are defined as both generalized coordinates and generalized speeds.")
  .run("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u3), check_duplicates = FALSE, u_auxiliary = list(u1, ua2, ua2))", e)
  expect_equal(.case("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u3), u_auxiliary = list(u1, ua2, ua3))", e), "ERR ValueError: The auxiliary speeds {u1(t)} are also defined as generalized coordinates or generalized speeds.")
  expect_equal(.case("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u3), u_auxiliary = list(q1, ua2, ua3))", e), "ERR ValueError: The auxiliary speeds {q1(t)} are also defined as generalized coordinates or generalized speeds.")
  expect_equal(.case("`_validate_coordinates`(list(q1, q2, q3), list(u1, u2, u3), u_auxiliary = list(ua1, ua2, ua2))", e), "ERR ValueError: The auxiliary speeds {ua2(t)} are duplicated, all auxiliary speeds should be unique.")
  .run("`_validate_coordinates`(list((q1 + q2), q3), is_dynamicsymbols = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(list((q1 + q2), q3))", e), "ERR ValueError: Generalized coordinate \"q1(t) + q2(t)\" is not a dynamicsymbol.")
  .run("`_validate_coordinates`(list(s1, q1, q2), list(0, u1, u2), is_dynamicsymbols = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(list(s1, q1, q2), list(0, u1, u2), is_dynamicsymbols = TRUE)", e), "ERR ValueError: Generalized coordinate \"s1\" is not a dynamicsymbol.\\nGeneralized speed \"0\" is not a dynamicsymbol.")
  .run("`_validate_coordinates`(list(((s1 + s2) + s3), q1), list(0, u1), is_dynamicsymbols = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(list(((s1 + s2) + s3), q1), list(0, u1), is_dynamicsymbols = TRUE)", e), "ERR ValueError: Generalized coordinate \"s1 + s2 + s3\" is not a dynamicsymbol.\\nGeneralized speed \"0\" is not a dynamicsymbol.")
  .run("`_validate_coordinates`(u_auxiliary = list(s1, ua1), is_dynamicsymbols = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(u_auxiliary = list(s1, ua1))", e), "ERR ValueError: Auxiliary speed \"s1\" is not a dynamicsymbol.")
  .run("t <- .pv_t()", e)
  .run("a <- pysymbols(\"a\")", e)
  .run(".tmp <- pylist(pysymbols(\"f1:3\", cls = Function)); f1 <- .tmp[[1]]; f2 <- .tmp[[2]]", e)
  .run("`_validate_coordinates`(list(f1(a), f2(a)), is_dynamicsymbols = FALSE)", e)
  expect_equal(.case("`_validate_coordinates`(list(f1(a), f2(a)))", e), "ERR ValueError: Generalized coordinate \"f1(a)\" is not a dynamicsymbol.\\nGeneralized coordinate \"f2(a)\" is not a dynamicsymbol.")
  expect_equal(.case("`_validate_coordinates`(speeds = list(f1(a), f2(a)))", e), "ERR ValueError: Generalized speed \"f1(a)\" is not a dynamicsymbol.\\nGeneralized speed \"f2(a)\" is not a dynamicsymbol.")
  .run("pysetattr(dynamicsymbols, \"_t\", a)", e)
  .run("`_validate_coordinates`(list(f1(a), f2(a)))", e)
  expect_equal(.case("`_validate_coordinates`(list(f1(t), f2(t)))", e), "ERR ValueError: Generalized coordinate \"f1(t)\" is not a dynamicsymbol.\\nGeneralized coordinate \"f2(t)\" is not a dynamicsymbol.")
})

test_that("mechanics/tests/test_functions.py::test_parse_linear_solver matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(tup(Matrix(3, 3, pysymbols(\"a:9\")), Matrix(3, 2, pysymbols(\"b:6\")))); A <- .tmp[[1]]; b <- .tmp[[2]]", e)
  expect_equal(.case("(`_parse_linear_solver`(\"LU\"))(A, b)", e), "Matrix([[(-a1*(b2 - (a5 - a2*a3/a0)*(b4 - (a7 - a1*a6/a0)*(b2 - a3*b0/a0)/(a4 - a1*a3/a0) - a6*b0/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0) - a3*b0/a0)/(a4 - a1*a3/a0) - a2*(b4 - (a7 - a1*a6/a0)*(b2 - a3*b0/a0)/(a4 - a1*a3/a0) - a6*b0/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0) + b0)/a0, (-a1*(b3 - (a5 - a2*a3/a0)*(b5 - (a7 - a1*a6/a0)*(b3 - a3*b1/a0)/(a4 - a1*a3/a0) - a6*b1/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0) - a3*b1/a0)/(a4 - a1*a3/a0) - a2*(b5 - (a7 - a1*a6/a0)*(b3 - a3*b1/a0)/(a4 - a1*a3/a0) - a6*b1/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0) + b1)/a0], [(b2 - (a5 - a2*a3/a0)*(b4 - (a7 - a1*a6/a0)*(b2 - a3*b0/a0)/(a4 - a1*a3/a0) - a6*b0/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0) - a3*b0/a0)/(a4 - a1*a3/a0), (b3 - (a5 - a2*a3/a0)*(b5 - (a7 - a1*a6/a0)*(b3 - a3*b1/a0)/(a4 - a1*a3/a0) - a6*b1/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0) - a3*b1/a0)/(a4 - a1*a3/a0)], [(b4 - (a7 - a1*a6/a0)*(b2 - a3*b0/a0)/(a4 - a1*a3/a0) - a6*b0/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0), (b5 - (a7 - a1*a6/a0)*(b3 - a3*b1/a0)/(a4 - a1*a3/a0) - a6*b1/a0)/(a8 - (a5 - a2*a3/a0)*(a7 - a1*a6/a0)/(a4 - a1*a3/a0) - a2*a6/a0)]])")
})

test_that("mechanics/tests/test_functions.py::test_deprecated_moved_functions matches SymPy", {
