  expect_equal(.case("inertia_of_point_mass(1, (pyattr(N, \"x\") + pyattr(N, \"y\")), N)", e), "(N.x|N.x) + (N.y|N.y) + 2*(N.z|N.z) - (N.x|N.y) - (N.y|N.x)")
  .run("p <- Particle(\"P\")", e)
