test_that("mechanics/tests/test_jointsmethod.py::test_chaos_pendulum matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"mA, mB, lA, lB, IAxx, IBxx, IByy, IBzz, g\")); mA <- .tmp[[1]]; mB <- .tmp[[2]]; lA <- .tmp[[3]]; lB <- .tmp[[4]]; IAxx <- .tmp[[5]]; IBxx <- .tmp[[6]]; IByy <- .tmp[[7]]; IBzz <- .tmp[[8]]; g <- .tmp[[9]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"theta phi omega alpha\")); theta <- .tmp[[1]]; phi <- .tmp[[2]]; omega <- .tmp[[3]]; alpha <- .tmp[[4]]", e)
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("B <- ReferenceFrame(\"B\")", e)
  .run("rod <- Body(\"rod\", mass = mA, frame = A, central_inertia = inertia(A, IAxx, IAxx, 0))", e)
  .run("plate <- Body(\"plate\", mass = mB, frame = B, central_inertia = inertia(B, IBxx, IByy, IBzz))", e)
  .run("C <- Body(\"C\")", e)
  .run("J1 <- PinJoint(\"J1\", C, rod, coordinates = theta, speeds = omega, child_point = ((-lA) * pyattr(rod, \"z\")), joint_axis = pyattr(C, \"y\"))", e)
  .run("J2 <- PinJoint(\"J2\", rod, plate, coordinates = phi, speeds = alpha, parent_point = ((lB - lA) * pyattr(rod, \"z\")), joint_axis = pyattr(rod, \"z\"))", e)
  .run("pycall(rod, \"apply_force\", ((mA * g) * pyattr(C, \"z\")))", e)
  .run("pycall(plate, \"apply_force\", ((mB * g) * pyattr(C, \"z\")))", e)
  .run("method <- JointsMethod(C, J1, J2)", e)
  .run("pycall(method, \"form_eoms\")", e)
  .run("MM <- pyattr(method, \"mass_matrix\")", e)
  .run("forcing <- pyattr(method, \"forcing\")", e)
  .run("rhs <- pycall(MM, \"LUsolve\", forcing)", e)
  .run("xd <- ((((((((((-2) * IBxx) * alpha) * omega) * sin(phi)) * cos(phi)) + (((((2 * IByy) * alpha) * omega) * sin(phi)) * cos(phi))) - (((g * lA) * mA) * sin(theta))) - (((g * lB) * mB) * sin(theta))) / ((((IAxx + (IBxx * pypow(sin(phi), 2))) + (IByy * pypow(cos(phi), 2))) + (pypow(lA, 2) * mA)) + (pypow(lB, 2) * mB)))", e)
  expect_equal(.case("pycall((pyget(rhs, 0) - xd), \"simplify\")", e), "0")
  .run("xd <- (((((IBxx - IByy) * pypow(omega, 2)) * sin(phi)) * cos(phi)) / IBzz)", e)
  expect_equal(.case("pycall((pyget(rhs, 1) - xd), \"simplify\")", e), "0")
})

