  .run(".tmp <- pylist(pysymbols(\"q u\")); q <- .tmp[[1]]; u <- .tmp[[2]]", e)
  .run("kd <- list((pycall(q, \"diff\", .pv_t()) - u))", e)
  .run(".tmp <- pylist(tup(ReferenceFrame(\"N\"), PhysPoint(\"O\"))); N <- .tmp[[1]]; O <- .tmp[[2]]", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("P <- Particle(\"P\", PhysPoint(\"P\"), m)", e)
  .run("pycall(pyattr(P, \"point\"), \"set_pos\", O, (l * ((sin(q) * pyattr(N, \"x\")) - (cos(q) * pyattr(N, \"y\")))))", e)
  .run("`F` <- tup(pyattr(P, \"point\"), (((-m) * g) * pyattr(N, \"y\")))", e)
  expect_equal(.case("KanesMethod(N, list(q), list(u), kd, bodies = list(P), forcelist = list(`F`))", e), "ERR ValueError: Generalized coordinate \"q\" is not a dynamicsymbol.\\nGeneralized speed \"u\" is not a dynamicsymbol.")
})

test_that("mechanics/tests/test_kane.py::test_one_dof matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q u\")); q <- .tmp[[1]]; u <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q u\", 1)); qd <- .tmp[[1]]; ud <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"m c k\")); m <- .tmp[[1]]; c <- .tmp[[2]]; k <- .tmp[[3]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("P <- PhysPoint(\"P\")", e)
  .run("pycall(P, \"set_vel\", N, (u * pyattr(N, \"x\")))", e)
  .run("kd <- list((qd - u))", e)
  .run("FL <- list(tup(P, ((((-k) * q) - (c * u)) * pyattr(N, \"x\"))))", e)
  .run("pa <- Particle(\"pa\", P, m)", e)
  .run("BL <- list(pa)", e)
  .run("KM <- KanesMethod(N, list(q), list(u), kd)", e)
  .run("pycall(KM, \"kanes_equations\", BL, FL)", e)
  expect_equal(.case("pyattr(KM, \"frame\")", e), "N")
  expect_equal(.case("pyattr(KM, \"bodies\")", e), "[pa]")
  expect_equal(.case("pyattr(KM, \"loads\")", e), "[(P, (-c*u(t) - k*q(t))*N.x)]")
  expect_equal(.case("pyattr(KM, \"bodylist\")", e), "[pa]")
  expect_equal(.case("pyattr(KM, \"forcelist\")", e), "[(P, (-c*u(t) - k*q(t))*N.x)]")
  .run("MM <- pyattr(KM, \"mass_matrix\")", e)
  .run("forcing <- pyattr(KM, \"forcing\")", e)
  .run("rhs <- (pycall(MM, \"inv\") * forcing)", e)
  expect_equal(.case("pyexpand(pyget(rhs, 0))", e), "-c*u(t)/m - k*q(t)/m")
  expect_equal(.case("pysimplify((pycall(KM, \"rhs\") - pycall(pyattr(KM, \"mass_matrix_full\"), \"LUsolve\", pyattr(KM, \"forcing_full\"))))", e), "Matrix([[0], [0]])")
  expect_equal(.case("pyget(pycall(KM, \"linearize\", A_and_B = TRUE), 0)", e), "Matrix([[0, 1], [-k/m, -c/m]])")
})

