test_that("mechanics/tests/test_kane.py::test_aux matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2 q3 u1 u2 u3\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; u1 <- .tmp[[4]]; u2 <- .tmp[[5]]; u3 <- .tmp[[6]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2 q3 u1 u2 u3\", 1)); q1d <- .tmp[[1]]; q2d <- .tmp[[2]]; q3d <- .tmp[[3]]; u1d <- .tmp[[4]]; u2d <- .tmp[[5]]; u3d <- .tmp[[6]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u4, u5, f1, f2\")); u4 <- .tmp[[1]]; u5 <- .tmp[[2]]; f1 <- .tmp[[3]]; f2 <- .tmp[[4]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u4, u5\", 1)); u4d <- .tmp[[1]]; u5d <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"r m g\")); r <- .tmp[[1]]; m <- .tmp[[2]]; g <- .tmp[[3]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("Y <- pycall(N, \"orientnew\", \"Y\", \"Axis\", list(q1, pyattr(N, \"z\")))", e)
  .run("L <- pycall(Y, \"orientnew\", \"L\", \"Axis\", list(q2, pyattr(Y, \"x\")))", e)
  .run("R <- pycall(L, \"orientnew\", \"R\", \"Axis\", list(q3, pyattr(L, \"y\")))", e)
  .run("w_R_N_qd <- pycall(R, \"ang_vel_in\", N)", e)
  .run("pycall(R, \"set_ang_vel\", N, (((u1 * pyattr(L, \"x\")) + (u2 * pyattr(L, \"y\"))) + (u3 * pyattr(L, \"z\"))))", e)
  .run("C <- PhysPoint(\"C\")", e)
  .run("pycall(C, \"set_vel\", N, ((u4 * pyattr(L, \"x\")) + (u5 * pyxor(pyattr(Y, \"z\"), pyattr(L, \"x\")))))", e)
  .run("Dmc <- pycall(C, \"locatenew\", \"Dmc\", (r * pyattr(L, \"z\")))", e)
  .run("pycall(Dmc, \"v2pt_theory\", C, N, R)", e)
  .run("pycall(Dmc, \"a2pt_theory\", C, N, R)", e)
  .run("I <- inertia(L, ((m / 4) * pypow(r, 2)), ((m / 2) * pypow(r, 2)), ((m / 4) * pypow(r, 2)))", e)
  .run("kd <- lapply(pyiter(L), function(uv) dot((pycall(R, \"ang_vel_in\", N) - w_R_N_qd), uv))", e)
  .run("ForceList <- list(tup(Dmc, (((-m) * g) * pyattr(Y, \"z\"))), tup(C, ((f1 * pyattr(L, \"x\")) + (f2 * pyxor(pyattr(Y, \"z\"), pyattr(L, \"x\"))))))", e)
  .run("BodyD <- RigidBody(\"BodyD\", Dmc, R, m, tup(I, Dmc))", e)
  .run("BodyList <- list(BodyD)", e)
  .run("KM <- KanesMethod(N, q_ind = list(q1, q2, q3), u_ind = list(u1, u2, u3, u4, u5), kd_eqs = kd)", e)
  .run(".tmp <- pylist(pycall(KM, \"kanes_equations\", BodyList, ForceList)); fr <- .tmp[[1]]; frstar <- .tmp[[2]]", e)
  .run("fr <- pycall(pycall(fr, \"subs\", pydict(list(u4d, u5d), list(0, 0))), \"subs\", pydict(list(u4, u5), list(0, 0)))", e)
  .run("frstar <- pycall(pycall(frstar, \"subs\", pydict(list(u4d, u5d), list(0, 0))), \"subs\", pydict(list(u4, u5), list(0, 0)))", e)
  .run("KM2 <- KanesMethod(N, q_ind = list(q1, q2, q3), u_ind = list(u1, u2, u3), kd_eqs = kd, u_auxiliary = list(u4, u5))", e)
  .run(".tmp <- pylist(pycall(KM2, \"kanes_equations\", BodyList, ForceList)); fr2 <- .tmp[[1]]; frstar2 <- .tmp[[2]]", e)
  .run("fr2 <- pycall(pycall(fr2, \"subs\", pydict(list(u4d, u5d), list(0, 0))), \"subs\", pydict(list(u4, u5), list(0, 0)))", e)
  .run("frstar2 <- pycall(pycall(frstar2, \"subs\", pydict(list(u4d, u5d), list(0, 0))), \"subs\", pydict(list(u4, u5), list(0, 0)))", e)
  .run("frstar <- pyinplace(frstar, \"simplify\")", e)
  .run("frstar2 <- pyinplace(frstar2, \"simplify\")", e)
  expect_equal(.case("pycall((fr - fr2), \"expand\")", e), "Matrix([[0], [0], [0], [0], [0]])")
  expect_equal(.case("pycall((frstar - frstar2), \"expand\")", e), "Matrix([[0], [0], [0], [0], [0]])")
})

test_that("mechanics/tests/test_kane.py::test_parallel_axis matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("gravity <- pysymbols(\"g\")", e)
  .run(".tmp <- pylist(pysymbols(\"k ls\")); k <- .tmp[[1]]; ls <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"a mA mC\")); a <- .tmp[[1]]; mA <- .tmp[[2]]; mC <- .tmp[[3]]", e)
  .run("`F` <- dynamicsymbols(\"F\")", e)
  .run(".tmp <- pylist(pysymbols(\"Ix Iy Iz\")); Ix <- .tmp[[1]]; Iy <- .tmp[[2]]; Iz <- .tmp[[3]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2\", 1)); q1d <- .tmp[[1]]; q2d <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u1 u2\")); u1 <- .tmp[[1]]; u2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u1 u2\", 1)); u1d <- .tmp[[1]]; u2d <- .tmp[[2]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("pycall(A, \"orient\", N, \"Axis\", list((-q2), pyattr(N, \"z\")))", e)
  .run("pycall(A, \"set_ang_vel\", N, ((-u2) * pyattr(N, \"z\")))", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("C <- pycall(O, \"locatenew\", \"C\", (q1 * pyattr(N, \"x\")))", e)
  .run("Ao <- pycall(C, \"locatenew\", \"Ao\", (a * pyattr(A, \"y\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(C, \"set_vel\", N, (u1 * pyattr(N, \"x\")))", e)
  .run("pycall(Ao, \"v2pt_theory\", C, N, A)", e)
  .run("Cart <- Particle(\"Cart\", C, mC)", e)
  .run("Pendulum <- RigidBody(\"Pendulum\", Ao, A, mA, tup(inertia(A, Ix, Iy, Iz), C))", e)
  .run("kindiffs <- list((q1d - u1), (q2d - u2))", e)
  .run("bodyList <- list(Cart, Pendulum)", e)
  .run("forceList <- list(tup(Ao, (((-pyattr(N, \"y\")) * gravity) * mA)), tup(C, (((-pyattr(N, \"y\")) * gravity) * mC)), tup(C, (((-pyattr(N, \"x\")) * k) * (q1 - ls))), tup(C, (pyattr(N, \"x\") * `F`)))", e)
  .run("km <- KanesMethod(N, list(q1, q2), list(u1, u2), kindiffs)", e)
  .run(".tmp <- pylist(pycall(km, \"kanes_equations\", bodyList, forceList)); fr <- .tmp[[1]]; frstar <- .tmp[[2]]", e)
  .run("mm <- pyattr(km, \"mass_matrix_full\")", e)
  expect_equal(.case("pyget(mm, 3, 3)", e), "Iz")
})

test_that("mechanics/tests/test_kane.py::test_input_format matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
