test_that("mechanics/tests/test_kane.py::test_issue_24887 matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"g l m c\")); g <- .tmp[[1]]; l <- .tmp[[2]]; m <- .tmp[[3]]; c <- .tmp[[4]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1:4 u1:4\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; u1 <- .tmp[[4]]; u2 <- .tmp[[5]]; u3 <- .tmp[[6]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("pycall(A, \"orient_body_fixed\", N, tup(q1, q2, q3), \"zxy\")", e)
  .run("N_w_A <- pycall(A, \"ang_vel_in\", N)", e)
  .run("kdes <- list((pycall(N_w_A, \"dot\", pyattr(A, \"x\")) - u1), (pycall(N_w_A, \"dot\", pyattr(A, \"y\")) - u2), (pycall(N_w_A, \"dot\", pyattr(A, \"z\")) - u3))", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
