  .run("P <- Particle(\"P\", Po, m)", e)
  .run("kane <- KanesMethod(N, list(q1, q2, q3), list(u1, u2, u3), kdes, bodies = list(P), forcelist = list(tup(Po, (((-m) * g) * pyattr(N, \"y\")))))", e)
  .run("pycall(kane, \"kanes_equations\")", e)
  .run("expected_md <- ((m * pypow(l, 2)) * Matrix(list(list(1, 0, 0), list(0, 0, 0), list(0, 0, 1))))", e)
  .run("expected_fd <- Matrix(list(list(((l * m) * ((g * ((sin(q1) * sin(q3)) - ((sin(q2) * cos(q1)) * cos(q3)))) - ((l * u2) * u3)))), list(0), list(((l * m) * (((-g) * ((sin(q1) * cos(q3)) + ((sin(q2) * sin(q3)) * cos(q1)))) + ((l * u1) * u2))))))", e)
  expect_equal(.case("pysimplify((pyattr(kane, \"mass_matrix\") - expected_md))", e), "Matrix([[0, 0, 0], [0, 0, 0], [0, 0, 0]])")
})

test_that("mechanics/tests/test_kane.py::test_Ars_warning matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("\"\\\\n    Tests that the additional warning is raised when the mass matrix is\\\\n    singular and that the correct error message is displayed.\\\\n    It is a simple pendulum on a post, where the pole must not move in the\\\\n    y direction. Clearly, if y is not the dependent speed,\\\\n    Ars will be singular.\\\\n    \"", e)
  .run(".tmp <- pylist(pysymbols(\"N A\", cls = ReferenceFrame)); N <- .tmp[[1]]; A <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"O P0 P1 P2\", cls = PhysPoint)); O <- .tmp[[1]]; P0 <- .tmp[[2]]; P1 <- .tmp[[3]]; P2 <- .tmp[[4]]", e)
  .run("t <- .pv_t()", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("l <- pysymbols(\"l\")", e)
  .run(".tmp <- pylist(dynamicsymbols(\"x y q\")); x <- .tmp[[1]]; y <- .tmp[[2]]; q <- .tmp[[3]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"ux uy uq\")); ux <- .tmp[[1]]; uy <- .tmp[[2]]; uq <- .tmp[[3]]", e)
  .run("pycall(A, \"orient_axis\", N, q, pyattr(N, \"z\"))", e)
  .run("pycall(P0, \"set_pos\", O, ((x * pyattr(N, \"x\")) + (y * pyattr(N, \"y\"))))", e)
  .run("pycall(P0, \"set_vel\", N, ((ux * pyattr(N, \"x\")) + (uy * pyattr(N, \"y\"))))", e)
  .run("pycall(P1, \"set_pos\", P0, ((2 * l) * pyattr(N, \"y\")))", e)
  .run("pycall(P2, \"set_pos\", P1, (l * pyattr(A, \"x\")))", e)
  .run("pycall(P2, \"v2pt_theory\", P1, N, A)", e)
  .run("kd <- Matrix(list((ux - pycall(x, \"diff\")), (uy - pycall(y, \"diff\")), (uq - pycall(q, \"diff\"))))", e)
  .run("config_constr <- Matrix(list(y))", e)
  .run("speed_constr <- pycall(config_constr, \"diff\", t)", e)
  .run("q_ind <- list(x, y)", e)
  .run("q_dep <- list(q)", e)
  .run("u_ind <- list(ux, uy)", e)
  .run("u_dep <- list(uq)", e)
  .run("msg <- \"Ars is singular, maybe due to a wrong set of dependent speeds. Try a different set of dependent speeds.\"", e)
  expect_equal(.case("KanesMethod(N, q_ind, u_ind, kd_eqs = kd, q_dependent = q_dep, u_dependent = u_dep, configuration_constraints = config_constr, velocity_constraints = speed_constr)", e), "ERR NonInvertibleMatrixError: Ars is singular, maybe due to a wrong set of dependent speeds. Try a different set of dependent speeds.")
})

test_that("mechanics/tests/test_kane.py::test_constraint_combos matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"l m\")); l <- .tmp[[1]]; m <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1:4 u1:4\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; u1 <- .tmp[[4]]; u2 <- .tmp[[5]]; u3 <- .tmp[[6]]", e)
  .run(".tmp <- pylist(tup(ReferenceFrame(\"N\"), ReferenceFrame(\"A\"))); N <- .tmp[[1]]; A <- .tmp[[2]]", e)
  .run("pycall(A, \"orient_body_fixed\", N, tup(q1, q2, q3), \"zxy\")", e)
  .run("N_w_A <- pycall(A, \"ang_vel_in\", N)", e)
  .run("kdes <- list((pycall(N_w_A, \"dot\", pyattr(A, \"x\")) - u1), (pycall(N_w_A, \"dot\", pyattr(A, \"y\")) - u2), (pycall(N_w_A, \"dot\", pyattr(A, \"z\")) - u3))", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("Po <- pycall(O, \"locatenew\", \"Po\", ((-l) * pyattr(A, \"y\")))", e)
  .run("pycall(Po, \"set_vel\", A, 0)", e)
  .run("P <- Particle(\"P\", Po, m)", e)
  .run("kane <- KanesMethod(N, list(q1, q2, q3), list(u1, u2, u3), kdes, bodies = list(P))", e)
  expect_equal(.case("pyattr(kane, \"holonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"nonholonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"velocity_constraints\")", e), "Matrix(0, 0, [])")
  .run("kane <- KanesMethod(N, list(q1, q2, q3), list(u1, u2, u3), kdes, bodies = list(P), configuration_constraints = list(), nonholonomic_constraints = list())", e)
  expect_equal(.case("pyattr(kane, \"holonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"nonholonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"velocity_constraints\")", e), "Matrix(0, 0, [])")
  .run("kane <- KanesMethod(N, list(q2, q3), list(u2, u3), kdes, bodies = list(P), q_dependent = list(q1), configuration_constraints = list((q1 - q2)), u_dependent = list(u1))", e)
  expect_equal(.case("pyattr(kane, \"holonomic_constraints\")", e), "Matrix([[q1(t) - q2(t)]])")
  expect_equal(.case("pyattr(kane, \"nonholonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"velocity_constraints\")", e), "Matrix([[(-1 + sin(q3(t))^2*cos(q2(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))))*u1(t)/cos(q3(t)) - u1(t)*sin(q3(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))) - u3(t)*sin(q3(t))*cos(q2(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))) + u3(t)/(sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))]])")
  .run("kane <- KanesMethod(N, list(q1, q2, q3), list(u2, u3), kdes, bodies = list(P), nonholonomic_constraints = list((u1 - u2)), u_dependent = list(u1))", e)
  expect_equal(.case("pyattr(kane, \"holonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"nonholonomic_constraints\")", e), "Matrix([[u1(t) - u2(t)]])")
  expect_equal(.case("pyattr(kane, \"velocity_constraints\")", e), "Matrix([[u1(t) - u2(t)]])")
  .run("kane <- KanesMethod(N, list(q2, q3), list(u2), kdes, bodies = list(P), configuration_constraints = list((q1 - q2)), q_dependent = list(q1), nonholonomic_constraints = list((u2 - u3)), u_dependent = list(u1, u3))", e)
  expect_equal(.case("pyattr(kane, \"holonomic_constraints\")", e), "Matrix([[q1(t) - q2(t)]])")
  expect_equal(.case("pyattr(kane, \"nonholonomic_constraints\")", e), "Matrix([[u2(t) - u3(t)]])")
  expect_equal(.case("pyattr(kane, \"velocity_constraints\")", e), "Matrix([[(-1 + sin(q3(t))^2*cos(q2(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))))*u1(t)/cos(q3(t)) - u1(t)*sin(q3(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))) - u3(t)*sin(q3(t))*cos(q2(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))) + u3(t)/(sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))], [u2(t) - u3(t)]])")
  .run("kane <- KanesMethod(N, list(q2, q3), list(u2), kdes, bodies = list(P), configuration_constraints = list((q1 - q2)), q_dependent = list(q1), velocity_constraints = list((pycall(q1, \"diff\") - pycall(q2, \"diff\")), (u2 - u3)), u_dependent = list(u1, u3))", e)
  expect_equal(.case("pyattr(kane, \"holonomic_constraints\")", e), "Matrix([[q1(t) - q2(t)]])")
  expect_equal(.case("pyattr(kane, \"nonholonomic_constraints\")", e), "Matrix(0, 0, [])")
  expect_equal(.case("pyattr(kane, \"velocity_constraints\")", e), "Matrix([[(-1 + sin(q3(t))^2*cos(q2(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))))*u1(t)/cos(q3(t)) - u1(t)*sin(q3(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))) - u3(t)*sin(q3(t))*cos(q2(t))/((sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))*cos(q3(t))) + u3(t)/(sin(q3(t))^2*cos(q2(t))/cos(q3(t)) + cos(q2(t))*cos(q3(t)))], [u2(t) - u3(t)]])")
  expect_equal(.case("KanesMethod(N, list(q1, q2, q3), list(u1, u2, u3), kdes, bodies = list(P), velocity_constraints = list(), nonholonomic_constraints = list())", e), "ERR ValueError: Only one of the kwargs velocity_constraints or nonholonomic_constraints can be supplied at a time.")
  expect_equal(.case("KanesMethod(N, list(q1, q2, q3), list(u2), kdes, bodies = list(P), configuration_constraints = list((q1 - q2)), q_dependent = list(), nonholonomic_constraints = list((u2 - u3)), u_dependent = list(u1, u3))", e), "ERR ValueError: There must be an equal number of dependent coordinates and configuration constraints.")
  expect_equal(.case("KanesMethod(N, list(q1, q2, q3), list(u1, u2), kdes, bodies = list(P), configuration_constraints = list((q1 - q2)), q_dependent = list(q1), nonholonomic_constraints = list((u2 - u3)), u_dependent = list(u3))", e), "ERR ValueError: The generalized coordinates {q1(t)} are duplicated, all generalized coordinates should be unique.")
})

