test_that("mechanics/tests/test_kane4.py::test_replace_qdots_in_force matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1, q2\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1, q2\", level = 1)); qd1 <- .tmp[[1]]; qd2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u1, u2\")); u1 <- .tmp[[1]]; u2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"l, m\")); l <- .tmp[[1]]; m <- .tmp[[2]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("A <- pycall(N, \"orientnew\", \"A\", \"Axis\", tup(q1, pyattr(N, \"z\")))", e)
  .run("B <- pycall(A, \"orientnew\", \"B\", \"Axis\", tup(q2, pyattr(N, \"z\")))", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (l * pyattr(A, \"x\")))", e)
  .run("pycall(P, \"v2pt_theory\", O, N, A)", e)
  .run("Q <- pycall(P, \"locatenew\", \"Q\", (l * pyattr(B, \"x\")))", e)
  .run("pycall(Q, \"v2pt_theory\", P, N, B)", e)
  .run("Ap <- Particle(\"Ap\", P, m)", e)
  .run("Bp <- Particle(\"Bp\", Q, m)", e)
  .run(".tmp <- pylist(pysymbols(\"sigma, delta\")); sig <- .tmp[[1]]; delta <- .tmp[[2]]", e)
  .run("Ta <- (((sig * q2) + (delta * qd2)) * pyattr(N, \"z\"))", e)
  .run("forces <- list(tup(A, Ta), tup(B, (-Ta)))", e)
  .run("kde1 <- list((u1 - qd1), (u2 - qd2))", e)
  .run("kde2 <- list((u1 - qd1), (u2 - (qd1 + qd2)))", e)
  .run("KM1 <- KanesMethod(N, list(q1, q2), list(u1, u2), kd_eqs = kde1)", e)
  .run(".tmp <- pylist(pycall(KM1, \"kanes_equations\", list(Ap, Bp), forces)); fr1 <- .tmp[[1]]; fstar1 <- .tmp[[2]]", e)
  .run("KM2 <- KanesMethod(N, list(q1, q2), list(u1, u2), kd_eqs = kde2)", e)
  .run(".tmp <- pylist(pycall(KM2, \"kanes_equations\", list(Ap, Bp), forces)); fr2 <- .tmp[[1]]; fstar2 <- .tmp[[2]]", e)
  .run("forcing_matrix_expected <- Matrix(list(list((((((m * pypow(l, 2)) * sin(q2)) * pypow(u2, 2)) + (sig * q2)) + (delta * (u2 - u1)))), list((((((m * pypow(l, 2)) * sin(q2)) * (-pypow(u1, 2))) - (sig * q2)) - (delta * (u2 - u1))))))", e)
  .run("mass_matrix_expected <- Matrix(list(list(((2 * m) * pypow(l, 2)), ((m * pypow(l, 2)) * cos(q2))), list(((m * pypow(l, 2)) * cos(q2)), (m * pypow(l, 2)))))", e)
  expect_equal(.case("pycall(pyattr(KM2, \"mass_matrix\"), \"expand\")", e), "Matrix([[2*l^2*m, l^2*m*cos(q2(t))], [l^2*m*cos(q2(t)), l^2*m]])")
  expect_equal(.case("pycall(pyattr(KM2, \"forcing\"), \"expand\")", e), "Matrix([[-delta*u1(t) + delta*u2(t) + l^2*m*u2(t)^2*sin(q2(t)) + sigma*q2(t)], [delta*u1(t) - delta*u2(t) - l^2*m*u1(t)^2*sin(q2(t)) - sigma*q2(t)]])")
  .run("fr1_expected <- Matrix(list(0, (-((sig * q2) + (delta * u2)))))", e)
  expect_equal(.case("pycall(fr1, \"expand\")", e), "Matrix([[0], [-delta*u2(t) - sigma*q2(t)]])")
  .run("fr2_expected <- Matrix(list(((sig * q2) + (delta * (u2 - u1))), (((-sig) * q2) - (delta * (u2 - u1)))))", e)
  expect_equal(.case("pycall(fr2, \"expand\")", e), "Matrix([[-delta*u1(t) + delta*u2(t) + sigma*q2(t)], [delta*u1(t) - delta*u2(t) - sigma*q2(t)]])")
  .run("Ta <- (((sig * q2) + (delta * u2)) * pyattr(N, \"z\"))", e)
  .run("forces <- list(tup(A, Ta), tup(B, (-Ta)))", e)
  .run("KM1 <- KanesMethod(N, list(q1, q2), list(u1, u2), kd_eqs = kde1)", e)
  .run(".tmp <- pylist(pycall(KM1, \"kanes_equations\", list(Ap, Bp), forces)); fr1 <- .tmp[[1]]; fstar1 <- .tmp[[2]]", e)
  expect_equal(.case("pycall(fr1, \"expand\")", e), "Matrix([[0], [-delta*u2(t) - sigma*q2(t)]])")
  .run("Ta <- (((sig * q2) + (delta * (u2 - u1))) * pyattr(N, \"z\"))", e)
  .run("forces <- list(tup(A, Ta), tup(B, (-Ta)))", e)
  .run("KM2 <- KanesMethod(N, list(q1, q2), list(u1, u2), kd_eqs = kde2)", e)
  .run(".tmp <- pylist(pycall(KM2, \"kanes_equations\", list(Ap, Bp), forces)); fr2 <- .tmp[[1]]; fstar2 <- .tmp[[2]]", e)
  expect_equal(.case("pycall(fr2, \"expand\")", e), "Matrix([[-delta*u1(t) + delta*u2(t) + sigma*q2(t)], [delta*u1(t) - delta*u2(t) - sigma*q2(t)]])")
  .run("Ta <- (((sig * q2) + (delta * pypow(qd2, 3))) * pyattr(N, \"z\"))", e)
  .run("forces <- list(tup(A, Ta), tup(B, (-Ta)))", e)
  .run("KM1 <- KanesMethod(N, list(q1, q2), list(u1, u2), kd_eqs = kde1)", e)
  .run(".tmp <- pylist(pycall(KM1, \"kanes_equations\", list(Ap, Bp), forces)); fr1 <- .tmp[[1]]; fstar1 <- .tmp[[2]]", e)
  .run("fr1_cubic_expected <- Matrix(list(0, (-((sig * q2) + (delta * pypow(u2, 3))))))", e)
  expect_equal(.case("pycall(fr1, \"expand\")", e), "Matrix([[0], [-delta*u2(t)^3 - sigma*q2(t)]])")
  .run("KM2 <- KanesMethod(N, list(q1, q2), list(u1, u2), kd_eqs = kde2)", e)
  .run(".tmp <- pylist(pycall(KM2, \"kanes_equations\", list(Ap, Bp), forces)); fr2 <- .tmp[[1]]; fstar2 <- .tmp[[2]]", e)
  .run("fr2_cubic_expected <- Matrix(list(((sig * q2) + (delta * pypow((u2 - u1), 3))), (((-sig) * q2) - (delta * pypow((u2 - u1), 3)))))", e)
  expect_equal(.case("pycall(fr2, \"expand\")", e), "Matrix([[-delta*u1(t)^3 + 3*delta*u1(t)^2*u2(t) - 3*delta*u1(t)*u2(t)^2 + delta*u2(t)^3 + sigma*q2(t)], [delta*u1(t)^3 - 3*delta*u1(t)^2*u2(t) + 3*delta*u1(t)*u2(t)^2 - delta*u2(t)^3 - sigma*q2(t)]])")
})

