try(.run("`_create_rolling_disc` <- function() { t <- .pv_t(); .tmp <- pylist(dynamicsymbols(\"q1:6 u1:6\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; q4 <- .tmp[[4]]; q5 <- .tmp[[5]]; u1 <- .tmp[[6]]; u2 <- .tmp[[7]]; u3 <- .tmp[[8]]; u4 <- .tmp[[9]]; u5 <- .tmp[[10]]; .tmp <- pylist(pysymbols(\"g r m\")); g <- .tmp[[1]]; r <- .tmp[[2]]; m <- .tmp[[3]]; ground <- RigidBody(\"ground\"); disc <- RigidBody(\"disk\", mass = m); pysetattr(disc, \"inertia\", tup((((m * pypow(r, 2)) / 4) * inertia(pyattr(disc, \"frame\"), 1, 2, 1)), pyattr(disc, \"masscenter\"))); pycall(pyattr(ground, \"masscenter\"), \"set_vel\", pyattr(ground, \"frame\"), 0); pycall(pyattr(disc, \"masscenter\"), \"set_vel\", pyattr(disc, \"frame\"), 0); int_frame <- ReferenceFrame(\"int_frame\"); pycall(int_frame, \"orient_body_fixed\", pyattr(ground, \"frame\"), tup(q1, q2, 0), \"zxy\"); pycall(pyattr(disc, \"frame\"), \"orient_axis\", int_frame, pyattr(int_frame, \"y\"), q3); g_w_d <- pycall(pyattr(disc, \"frame\"), \"ang_vel_in\", pyattr(ground, \"frame\")); pycall(pyattr(disc, \"frame\"), \"set_ang_vel\", pyattr(ground, \"frame\"), (((u1 * pyattr(disc, \"x\")) + (u2 * pyattr(disc, \"y\"))) + (u3 * pyattr(disc, \"z\")))); cp <- pycall(pyattr(ground, \"masscenter\"), \"locatenew\", \"contact_point\", ((q4 * pyattr(ground, \"x\")) + (q5 * pyattr(ground, \"y\")))); pycall(cp, \"set_vel\", pyattr(ground, \"frame\"), ((u4 * pyattr(ground, \"x\")) + (u5 * pyattr(ground, \"y\")))); pycall(pyattr(disc, \"masscenter\"), \"set_pos\", cp, (r * pyattr(int_frame, \"z\"))); pycall(pyattr(disc, \"masscenter\"), \"set_vel\", pyattr(ground, \"frame\"), cross(pycall(pyattr(disc, \"frame\"), \"ang_vel_in\", pyattr(ground, \"frame\")), pycall(pyattr(disc, \"masscenter\"), \"pos_from\", cp))); kdes <- list((pycall(g_w_d, \"dot\", pyattr(disc, \"x\")) - u1), (pycall(g_w_d, \"dot\", pyattr(disc, \"y\")) - u2), (pycall(g_w_d, \"dot\", pyattr(disc, \"z\")) - u3), (pycall(q4, \"diff\", t) - u4), (pycall(q5, \"diff\", t) - u5)); v0 <- (pycall(cp, \"vel\", pyattr(ground, \"frame\")) + cross(pycall(pyattr(disc, \"frame\"), \"ang_vel_in\", int_frame), pycall(cp, \"pos_from\", pyattr(disc, \"masscenter\")))); fnh <- list(pycall(v0, \"dot\", pyattr(ground, \"x\")), pycall(v0, \"dot\", pyattr(ground, \"y\"))); loads <- list(tup(pyattr(disc, \"masscenter\"), (((-pyattr(disc, \"mass\")) * g) * pyattr(ground, \"z\")))); bodies <- list(disc); return(pydict(list(\"frame\", \"q_ind\", \"u_ind\", \"u_dep\", \"kdes\", \"fnh\", \"bodies\", \"loads\"), list(pyattr(ground, \"frame\"), list(q1, q2, q3, q4, q5), list(u1, u2, u3), list(u4, u5), kdes, fnh, bodies, loads))) }; `_verify_rolling_disc_numerically` <- function(kane, all_zero = FALSE) { .tmp <- pylist(tup(dynamicsymbols(\"q1:6\"), dynamicsymbols(\"u1:6\"), pysymbols(\"g r m\"))); q <- .tmp[[1]]; u <- .tmp[[2]]; p <- .tmp[[3]]; eval_sys <- lambdify(tup(q, u, p), tup(pyattr(kane, \"mass_matrix_full\"), pyattr(kane, \"forcing_full\")), cse = TRUE); solve_sys <- function(q, u, p) pydocall(pyattr(Matrix, \"LUsolve\"), list(), lapply(pyiter(eval_sys(q, u, p)), function(mat) Matrix(mat))); solve_u_dep <- lambdify(tup(q, pyslice(u, NULL, 3, NULL), p), (pyattr(kane, \"_Ars\") * Matrix(pyslice(u, NULL, 3, NULL))), cse = TRUE); eps <- Float(1e-10); p_vals <- tup(Float(9.81), Float(0.26), Float(3.43)); q_vals <- tup(Float(0.3), Float(0.1), Float(1.97), (-Float(0.35)), Float(2.27)); u_vals <- list((-Float(0.2)), Float(1.3), Float(0.15)); pycall(u_vals, \"extend\", pyget(solve_u_dep(q_vals, u_vals, p_vals), pysl(NULL, 2), 0)); expected <- Matrix(list(Float(0.126603940595934), Float(0.21594257160166), Float(1.28736069604936), Float(0.319764288376543), Float(0.0989146857254898), (-Float(0.925848952664489)), (-Float(0.0181350656532944)), Float(2.91695398184589), (-Float(0.00992793421754526)), Float(0.0412861634829171))); NULL; q_vals <- tup(Float(3.97), (-Float(0.28)), Float(8.2), (-Float(0.35)), Float(2.27)); u_vals <- list((-Float(0.25)), (-Float(2.2)), Float(0.62)); pycall(u_vals, \"extend\", pyget(solve_u_dep(q_vals, u_vals, p_vals), pysl(NULL, 2), 0)); expected <- Matrix(list(Float(0.0259159090798597), Float(0.668041660387416), (-Float(2.19283799213811)), Float(0.385441810852219), Float(0.420109283790573), Float(1.45030568179066), (-Float(0.0110924422400793)), (-Float(8.3561784018604)), (-Float(0.154098542632173)), (-Float(0.14610266441001)))); NULL; if (pybool(all_zero)) { q_vals <- tup(0, 0, 0, 0, 0); u_vals <- tup(0, 0, 0, 0, 0); NULL } else { NULL } }", .menv), silent = TRUE)
