test_that("mechanics/tests/test_lagrange.py::test_invalid_coordinates matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"l m g\")); l <- .tmp[[1]]; m <- .tmp[[2]]; g <- .tmp[[3]]", e)
  .run("q <- pysymbols(\"q\")", e)
  .run(".tmp <- pylist(tup(ReferenceFrame(\"N\"), PhysPoint(\"O\"))); N <- .tmp[[1]]; O <- .tmp[[2]]", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("P <- Particle(\"P\", PhysPoint(\"P\"), m)", e)
  .run("pycall(pyattr(P, \"point\"), \"set_pos\", O, (l * ((sin(q) * pyattr(N, \"x\")) - (cos(q) * pyattr(N, \"y\")))))", e)
  .run("pysetattr(P, \"potential_energy\", ((m * g) * pycall(pycall(pyattr(P, \"point\"), \"pos_from\", O), \"dot\", pyattr(N, \"y\"))))", e)
  .run("L <- Lagrangian(N, P)", e)
  expect_equal(.case("LagrangesMethod(L, list(q), bodies = list(P))", e), "ERR ValueError: Generalized coordinate \"q\" is not a dynamicsymbol.")
})

test_that("mechanics/tests/test_lagrange.py::test_disc_on_an_incline_plane matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"y theta\")); y <- .tmp[[1]]; theta <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"y theta\", 1)); yd <- .tmp[[1]]; thetad <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"m g R l alpha\")); m <- .tmp[[1]]; g <- .tmp[[2]]; R <- .tmp[[3]]; l <- .tmp[[4]]; alpha <- .tmp[[5]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("A <- pycall(N, \"orientnew\", \"A\", \"Axis\", list(((S_Pi / 2) - alpha), pyattr(N, \"z\")))", e)
  .run("B <- pycall(A, \"orientnew\", \"B\", \"Axis\", list((-theta), pyattr(A, \"z\")))", e)
  .run("Do <- PhysPoint(\"Do\")", e)
  .run("pycall(Do, \"set_vel\", N, (yd * pyattr(A, \"x\")))", e)
  .run("I <- ((((m * pypow(R, 2)) / 2) * pyattr(B, \"z\")) | pyattr(B, \"z\"))", e)
  .run("D <- RigidBody(\"D\", Do, B, m, tup(I, Do))", e)
  .run("pysetattr(D, \"potential_energy\", (((m * g) * (l - y)) * sin(alpha)))", e)
  .run("L <- Lagrangian(N, D)", e)
  .run("q <- list(y, theta)", e)
  .run("hol_coneqs <- list((y - (R * theta)))", e)
  .run("m <- LagrangesMethod(L, q, hol_coneqs = hol_coneqs)", e)
  expect_equal(.case("pyattr(m, \"holonomic_constraints\")", e), "Matrix([[-R*theta(t) + y(t)]])")
  expect_equal(.case("pyattr(m, \"velocity_constraints\")", e), "Matrix([[-R*Derivative(theta(t), t) + Derivative(y(t), t)]])")
  .run("pycall(m, \"form_lagranges_equations\")", e)
  expect_equal(.case("pyattr(m, \"lam_coeffs\")", e), "Matrix([[-1, R]])")
  expect_equal(.case("pyattr(m, \"lam_coeffs\")", e), "Matrix([[-1, R]])")
  .run("rhs <- pycall(m, \"rhs\")", e)
  .run("rhs <- pyinplace(rhs, \"simplify\")", e)
  expect_equal(.case("pyget(rhs, 2)", e), "2*g*sin(alpha)/3")
})

