test_that("mechanics/tests/test_lagrange.py::test_nonminimal_pendulum matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1:3\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1:3\", level = 1)); q1d <- .tmp[[1]]; q2d <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"L, m, t\")); L <- .tmp[[1]]; m <- .tmp[[2]]; t <- .tmp[[3]]", e)
  .run("g <- Float(9.8)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("pN <- PhysPoint(\"N*\")", e)
  .run("pycall(pN, \"set_vel\", N, 0)", e)
  .run("P <- pycall(pN, \"locatenew\", \"P1\", ((q1 * pyattr(N, \"x\")) + (q2 * pyattr(N, \"y\"))))", e)
  .run("pycall(P, \"set_vel\", N, pycall(pycall(P, \"pos_from\", pN), \"dt\", N))", e)
  .run("pP <- Particle(\"pP\", P, m)", e)
  .run("f_c <- Matrix(list(((pypow(q1, 2) + pypow(q2, 2)) - pypow(L, 2))))", e)
  .run("Lag <- Lagrangian(N, pP)", e)
  .run("LM <- LagrangesMethod(Lag, list(q1, q2), hol_coneqs = f_c, forcelist = list(tup(P, ((m * g) * pyattr(N, \"x\")))), frame = N)", e)
  expect_equal(.case("pyattr(LM, \"frame\")", e), "N")
  .run("pycall(LM, \"form_lagranges_equations\")", e)
  .run("lam1 <- pyget(pyattr(LM, \"lam_vec\"), 0, 0)", e)
  .run("eom_sol <- Matrix(list(list((((m * Derivative(q1, t, t)) - (Float(9.8) * m)) + ((2 * lam1) * q1))), list(((m * Derivative(q2, t, t)) + ((2 * lam1) * q2)))))", e)
  expect_equal(.case("pyattr(LM, \"eom\")", e), "Matrix([[m*Derivative(q1(t), (t, 2)) - 9.8*m + 2*lam1(t)*q1(t)], [m*Derivative(q2(t), (t, 2)) + 2*lam1(t)*q2(t)]])")
  .run("lam_sol <- Matrix(list(((((Float(19.6) * q1) + (2 * pypow(q1d, 2))) + (2 * pypow(q2d, 2))) / (((4 * pypow(q1, 2)) / m) + ((4 * pypow(q2, 2)) / m)))))", e)
  expect_equal(.case("pyattr(LM, \"loads\")", e), "[(P1, 9.8*m*N.x)]")
  expect_equal(.case("pyattr(LM, \"forcelist\")", e), "[(P1, 9.8*m*N.x)]")
})

test_that("mechanics/tests/test_lagrange.py::test_dub_pen matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2\", 1)); q1d <- .tmp[[1]]; q2d <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2\", 2)); q1dd <- .tmp[[1]]; q2dd <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u1 u2\")); u1 <- .tmp[[1]]; u2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"u1 u2\", 1)); u1d <- .tmp[[1]]; u2d <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"l m g\")); l <- .tmp[[1]]; m <- .tmp[[2]]; g <- .tmp[[3]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("A <- pycall(N, \"orientnew\", \"A\", \"Axis\", list(q1, pyattr(N, \"z\")))", e)
  .run("B <- pycall(N, \"orientnew\", \"B\", \"Axis\", list(q2, pyattr(N, \"z\")))", e)
  .run("pycall(A, \"set_ang_vel\", N, (q1d * pyattr(A, \"z\")))", e)
  .run("pycall(B, \"set_ang_vel\", N, (q2d * pyattr(A, \"z\")))", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (l * pyattr(A, \"x\")))", e)
  .run("R <- pycall(P, \"locatenew\", \"R\", (l * pyattr(B, \"x\")))", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("pycall(P, \"v2pt_theory\", O, N, A)", e)
  .run("pycall(R, \"v2pt_theory\", P, N, B)", e)
  .run("ParP <- Particle(\"ParP\", P, m)", e)
  .run("ParR <- Particle(\"ParR\", R, m)", e)
  .run("pysetattr(ParP, \"potential_energy\", ((((-m) * g) * l) * cos(q1)))", e)
  .run("pysetattr(ParR, \"potential_energy\", (((((-m) * g) * l) * cos(q1)) - (((m * g) * l) * cos(q2))))", e)
  .run("L <- Lagrangian(N, ParP, ParR)", e)
  .run("lm <- LagrangesMethod(L, list(q1, q2), bodies = list(ParP, ParR))", e)
  .run("pycall(lm, \"form_lagranges_equations\")", e)
  expect_equal(.case("pysimplify((((l * m) * (((((((2 * g) * sin(q1)) + (((l * sin(q1)) * sin(q2)) * q2dd)) + (((l * sin(q1)) * cos(q2)) * pypow(q2d, 2))) - (((l * sin(q2)) * cos(q1)) * pypow(q2d, 2))) + (((l * cos(q1)) * cos(q2)) * q2dd)) + ((2 * l) * q1dd))) - pyget(pyattr(lm, \"eom\"), 0)))", e), "0")
  expect_equal(.case("pysimplify((((l * m) * ((((((g * sin(q2)) + (((l * sin(q1)) * sin(q2)) * q1dd)) - (((l * sin(q1)) * cos(q2)) * pypow(q1d, 2))) + (((l * sin(q2)) * cos(q1)) * pypow(q1d, 2))) + (((l * cos(q1)) * cos(q2)) * q1dd)) + (l * q2dd))) - pyget(pyattr(lm, \"eom\"), 1)))", e), "0")
  expect_equal(.case("pyattr(lm, \"bodies\")", e), "[ParP, ParR]")
})

test_that("mechanics/tests/test_lagrange.py::test_rolling_disc matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2 q3\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1 q2 q3\", 1)); q1d <- .tmp[[1]]; q2d <- .tmp[[2]]; q3d <- .tmp[[3]]", e)
  .run(".tmp <- pylist(pysymbols(\"r m g\")); r <- .tmp[[1]]; m <- .tmp[[2]]; g <- .tmp[[3]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("Y <- pycall(N, \"orientnew\", \"Y\", \"Axis\", list(q1, pyattr(N, \"z\")))", e)
  .run("L <- pycall(Y, \"orientnew\", \"L\", \"Axis\", list(q2, pyattr(Y, \"x\")))", e)
  .run("R <- pycall(L, \"orientnew\", \"R\", \"Axis\", list(q3, pyattr(L, \"y\")))", e)
  .run("C <- PhysPoint(\"C\")", e)
  .run("pycall(C, \"set_vel\", N, 0)", e)
  .run("Dmc <- pycall(C, \"locatenew\", \"Dmc\", (r * pyattr(L, \"z\")))", e)
  .run("pycall(Dmc, \"v2pt_theory\", C, N, R)", e)
  .run("I <- inertia(L, ((m / 4) * pypow(r, 2)), ((m / 2) * pypow(r, 2)), ((m / 4) * pypow(r, 2)))", e)
  .run("BodyD <- RigidBody(\"BodyD\", Dmc, R, m, tup(I, Dmc))", e)
  .run("pysetattr(BodyD, \"potential_energy\", ((((-m) * g) * r) * cos(q2)))", e)
  .run("Lag <- Lagrangian(N, BodyD)", e)
  .run("q <- list(q1, q2, q3)", e)
  .run("q1 <- Function(\"q1\")", e)
  .run("q2 <- Function(\"q2\")", e)
  .run("q3 <- Function(\"q3\")", e)
  .run("l <- LagrangesMethod(Lag, q)", e)
  expect_equal(.case("pyattr(l, \"nonholonomic_constraints\")", e), "Matrix(0, 0, [])")
  .run("pycall(l, \"form_lagranges_equations\")", e)
  .run("RHS <- pycall(l, \"rhs\")", e)
  .run("RHS <- pyinplace(RHS, \"simplify\")", e)
  .run("t <- pysymbols(\"t\")", e)
  expect_equal(.case("pyslice(pyattr(l, \"mass_matrix\"), 3, 6, NULL)", e), "[0, 5*m*r^2/4, 0]")
  expect_equal(.case("pycall(pyget(RHS, 4), \"simplify\")", e), "(-8*g*sin(q2(t)) + r*(5*sin(2*q2(t))*Derivative(q1(t), t) + 12*cos(q2(t))*Derivative(q3(t), t))*Derivative(q1(t), t))/(10*r)")
  expect_equal(.case("pyget(RHS, 5)", e), "(-5*cos(q2(t))*Derivative(q1(t), t) + 6*tan(q2(t))*Derivative(q3(t), t) + 4*Derivative(q1(t), t)/cos(q2(t)))*Derivative(q2(t), t)")
  .run("contact_point_vel <- (pycall(C, \"vel\", N) + pycall(pycall(R, \"ang_vel_in\", N), \"cross\", ((-r) * pyattr(L, \"z\"))))", e)
  .run("nonholonomic <- list(pycall(contact_point_vel, \"dot\", pyattr(Y, \"x\")), pycall(contact_point_vel, \"dot\", pyattr(Y, \"y\")))", e)
  .run("l <- LagrangesMethod(Lag, q, nonhol_coneqs = nonholonomic)", e)
  expect_equal(.case("pyattr(l, \"nonholonomic_constraints\")", e), "Matrix([[-r*(sin(q2(t))*Derivative(q1(t), t) + Derivative(q3(t), t))], [r*cos(q2(t))*Derivative(q2(t), t)]])")
  expect_equal(.case("pyattr(l, \"velocity_constraints\")", e), "Matrix([[-r*(sin(q2(t))*Derivative(q1(t), t) + Derivative(q3(t), t))], [r*cos(q2(t))*Derivative(q2(t), t)]])")
})

