test_that("mechanics/tests/test_lagrange2.py::test_lagrange_2forces matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1, q2\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1, q2\", 1)); q1d <- .tmp[[1]]; q2d <- .tmp[[2]]", e)
  .run(".tmp <- pylist(pysymbols(\"m, k, nu\")); m <- .tmp[[1]]; k <- .tmp[[2]]; nu <- .tmp[[3]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("P1 <- pycall(O, \"locatenew\", \"P1\", (q1 * pyattr(N, \"x\")))", e)
  .run("pycall(P1, \"set_vel\", N, (q1d * pyattr(N, \"x\")))", e)
  .run("P2 <- pycall(O, \"locatenew\", \"P1\", (q2 * pyattr(N, \"x\")))", e)
  .run("pycall(P2, \"set_vel\", N, (q2d * pyattr(N, \"x\")))", e)
  .run("pP1 <- Particle(\"pP1\", P1, m)", e)
  .run("pysetattr(pP1, \"potential_energy\", ((k * pypow(q1, 2)) / 2))", e)
  .run("pP2 <- Particle(\"pP2\", P2, m)", e)
  .run("pysetattr(pP2, \"potential_energy\", ((k * pypow((q1 - q2), 2)) / 2))", e)
  .run("forcelist <- list(tup(P1, (((-nu) * q1d) * pyattr(N, \"x\"))), tup(P2, (((-nu) * q2d) * pyattr(N, \"x\"))))", e)
  .run("lag <- Lagrangian(N, pP1, pP2)", e)
  .run("l_method <- LagrangesMethod(lag, tup(q1, q2), forcelist = forcelist, frame = N)", e)
  .run("pycall(l_method, \"form_lagranges_equations\")", e)
  .run("eq1 <- pyget(pyattr(l_method, \"eom\"), 0)", e)
  expect_equal(.case("pycall(eq1, \"diff\", q1d)", e), "nu")
  .run("eq2 <- pyget(pyattr(l_method, \"eom\"), 1)", e)
  expect_equal(.case("pycall(eq2, \"diff\", q2d)", e), "nu")
})

