test_that("mechanics/tests/test_linearity_of_velocity_constraints.py::test_linearity_of_motion_constraints matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("t <- .pv_t()", e)
  .run(".tmp <- pylist(tup(ReferenceFrame(\"N\"), ReferenceFrame(\"A\"))); N <- .tmp[[1]]; A <- .tmp[[2]]", e)
  .run(".tmp <- pylist(tup(PhysPoint(\"O\"), PhysPoint(\"P\"))); O <- .tmp[[1]]; P <- .tmp[[2]]", e)
  .run("pycall(O, \"set_vel\", N, 0)", e)
  .run("l <- pysymbols(\"l\")", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q x y u ux uy\")); q <- .tmp[[1]]; x <- .tmp[[2]]; y <- .tmp[[3]]; u <- .tmp[[4]]; ux <- .tmp[[5]]; uy <- .tmp[[6]]", e)
  .run("pycall(A, \"orient_axis\", N, q, pyattr(N, \"z\"))", e)
  .run("pycall(A, \"set_ang_vel\", N, (u * pyattr(N, \"z\")))", e)
  .run("pycall(P, \"set_pos\", O, ((-l) * pyattr(A, \"y\")))", e)
  .run("pycall(P, \"v2pt_theory\", O, N, A)", e)
  .run("kd <- list((u - pycall(q, \"diff\", t)), (ux - pycall(x, \"diff\", t)), (uy - pycall(y, \"diff\", t)))", e)
  .run("config_constr <- list((x - (l * sin(q))), (y - (l * cos(q))))", e)
  .run("q_ind <- list(q)", e)
  .run("q_dep <- list(x, y)", e)
  .run("u_ind <- list(u)", e)
  .run("u_dep <- list(ux, uy)", e)
  .run("speed_constr <- list((ux - ((l * pycall(q, \"diff\", t)) * cos(q))), (sin(uy) + ((l * pycall(q, \"diff\", t)) * sin(q))))", e)
  expect_equal(.case("KanesMethod(N, q_ind = q_ind, q_dependent = q_dep, u_ind = u_ind, u_dependent = u_dep, kd_eqs = kd, configuration_constraints = config_constr, velocity_constraints = speed_constr)", e), "ERR NonlinearError: nonlinear term: sin(uy(t))")
})

