  .run("g <- Float(9.8)", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("pN <- PhysPoint(\"N*\")", e)
  .run("pycall(pN, \"set_vel\", N, 0)", e)
  .run("A <- pycall(N, \"orientnew\", \"A\", \"axis\", list(q1, pyattr(N, \"z\")))", e)
  .run("pycall(A, \"set_ang_vel\", N, (q1d * pyattr(N, \"z\")))", e)
  .run("P <- pycall(pN, \"locatenew\", \"P\", (L * pyattr(A, \"x\")))", e)
