  expect_equal(.case("pyattr(pyattr(p, \"masscenter\"), \"name\")", e), "P_masscenter")
  expect_equal(.case("pyattr(p, \"potential_energy\")", e), "0")
  expect_equal(.case("pycall(p, \"__str__\")", e), "P")
  expect_equal(.case("pycall(p, \"__repr__\")", e), "Particle('P', masscenter=P_masscenter, mass=P_mass)")
  expect_equal(.case("pyattr(p, \"frame\")", e), "ERR AttributeError: 'Particle' object has no attribute 'frame'")
})

test_that("mechanics/tests/test_particle.py::test_particle matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"m m2 v1 v2 v3 r g h\")); m <- .tmp[[1]]; m2 <- .tmp[[2]]; v1 <- .tmp[[3]]; v2 <- .tmp[[4]]; v3 <- .tmp[[5]]; r <- .tmp[[6]]; g <- .tmp[[7]]; h <- .tmp[[8]]", e)
  .run("P <- PhysPoint(\"P\")", e)
  .run("P2 <- PhysPoint(\"P2\")", e)
  .run("p <- Particle(\"pa\", P, m)", e)
  expect_equal(.case("pyisinstance(p, BodyBase)", e), "True")
  expect_equal(.case("pyattr(p, \"mass\")", e), "m")
  expect_equal(.case("pyattr(p, \"point\")", e), "P")
  .run("pysetattr(p, \"mass\", m2)", e)
  expect_equal(.case("pyattr(p, \"mass\")", e), "m2")
  .run("pysetattr(p, \"point\", P2)", e)
  expect_equal(.case("pyattr(p, \"point\")", e), "P2")
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("pycall(P2, \"set_pos\", O, (r * pyattr(N, \"y\")))", e)
  .run("pycall(P2, \"set_vel\", N, (v1 * pyattr(N, \"x\")))", e)
  expect_equal(.case("Particle(P, P, m)", e), "ERR TypeError: Supply a valid name.")
  expect_equal(.case("Particle(\"pa\", m, m)", e), "ERR TypeError: The body's center of mass must be a Point object.")
  expect_equal(.case("pycall(p, \"linear_momentum\", N)", e), "m2*v1*N.x")
  expect_equal(.case("pycall(p, \"angular_momentum\", O, N)", e), "- m2*r*v1*N.z")
  .run("pycall(P2, \"set_vel\", N, (v2 * pyattr(N, \"y\")))", e)
  expect_equal(.case("pycall(p, \"linear_momentum\", N)", e), "m2*v2*N.y")
  expect_equal(.case("pycall(p, \"angular_momentum\", O, N)", e), "0")
  .run("pycall(P2, \"set_vel\", N, (v3 * pyattr(N, \"z\")))", e)
  expect_equal(.case("pycall(p, \"linear_momentum\", N)", e), "m2*v3*N.z")
  expect_equal(.case("pycall(p, \"angular_momentum\", O, N)", e), "m2*r*v3*N.x")
  .run("pycall(P2, \"set_vel\", N, (((v1 * pyattr(N, \"x\")) + (v2 * pyattr(N, \"y\"))) + (v3 * pyattr(N, \"z\"))))", e)
  expect_equal(.case("pycall(p, \"linear_momentum\", N)", e), "m2*v1*N.x + m2*v2*N.y + m2*v3*N.z")
  expect_equal(.case("pycall(p, \"angular_momentum\", O, N)", e), "m2*r*v3*N.x - m2*r*v1*N.z")
  .run("pysetattr(p, \"potential_energy\", ((m * g) * h))", e)
  expect_equal(.case("pyattr(p, \"potential_energy\")", e), "g*h*m")
  .run("expected_kinetic_energy <- ((m2 * ((pypow(v1, 2) + pypow(v2, 2)) + pypow(v3, 2))) / 2)", e)
  expect_equal(.case("pycall((pycall(p, \"kinetic_energy\", N) - expected_kinetic_energy), \"expand\")", e), "0")
})

test_that("mechanics/tests/test_particle.py::test_parallel_axis matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("N <- ReferenceFrame(\"N\")", e)
  .run(".tmp <- pylist(pysymbols(\"m, a, b\")); m <- .tmp[[1]]; a <- .tmp[[2]]; b <- .tmp[[3]]", e)
  .run("o <- PhysPoint(\"o\")", e)
  .run("p <- pycall(o, \"locatenew\", \"p\", ((a * pyattr(N, \"x\")) + (b * pyattr(N, \"y\"))))", e)
  .run("P <- Particle(\"P\", o, m)", e)
  .run("Ip <- pycall(P, \"parallel_axis\", p, N)", e)
  .run("Ip_expected <- inertia(N, (m * pypow(b, 2)), (m * pypow(a, 2)), (m * (pypow(a, 2) + pypow(b, 2))), ixy = (((-m) * a) * b))", e)
  expect_equal(.case("Ip", e), "b^2*m*(N.x|N.x) + a^2*m*(N.y|N.y) + m*(a^2 + b^2)*(N.z|N.z) - a*b*m*(N.x|N.y) - a*b*m*(N.y|N.x)")
})

