  expect_equal(.case("pycall(pyattr(self, \"pathway\"), \"to_loads\", pyattr(self, \"F\"))", e), "[(pA, - F*q1(t)/sqrt(q1(t)^2)*N.x), (pB, F*q1(t)/sqrt(q1(t)^2)*N.x)]")
})

