test_that("mechanics/tests/test_pathway.py::TestLinearPathway::test_3D_pathway_to_loads matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\")))", e)
  .run("pysetattr(self, \"q1\", dynamicsymbols(\"q1\"))", e)
  .run("pysetattr(self, \"q2\", dynamicsymbols(\"q2\"))", e)
  .run("pysetattr(self, \"q3\", dynamicsymbols(\"q3\"))", e)
  .run("pysetattr(self, \"q1d\", dynamicsymbols(\"q1\", 1))", e)
  .run("pysetattr(self, \"q2d\", dynamicsymbols(\"q2\", 1))", e)
  .run("pysetattr(self, \"q3d\", dynamicsymbols(\"q3\", 1))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pA\"), (((pyattr(self, \"q1\") * pyattr(pyattr(self, \"N\"), \"x\")) - (pyattr(self, \"q2\") * pyattr(pyattr(self, \"N\"), \"y\"))) + ((2 * pyattr(self, \"q3\")) * pyattr(pyattr(self, \"N\"), \"z\"))))", e)
  .run("length <- sqrt(((pypow(pyattr(self, \"q1\"), 2) + pypow(pyattr(self, \"q2\"), 2)) + (4 * pypow(pyattr(self, \"q3\"), 2))))", e)
  .run("pO_force <- ((((((-pyattr(self, \"F\")) * pyattr(self, \"q1\")) * pyattr(pyattr(self, \"N\"), \"x\")) / length) + (((pyattr(self, \"F\") * pyattr(self, \"q2\")) * pyattr(pyattr(self, \"N\"), \"y\")) / length)) - ((((2 * pyattr(self, \"F\")) * pyattr(self, \"q3\")) * pyattr(pyattr(self, \"N\"), \"z\")) / length))", e)
  .run("pI_force <- (((((pyattr(self, \"F\") * pyattr(self, \"q1\")) * pyattr(pyattr(self, \"N\"), \"x\")) / length) - (((pyattr(self, \"F\") * pyattr(self, \"q2\")) * pyattr(pyattr(self, \"N\"), \"y\")) / length)) + ((((2 * pyattr(self, \"F\")) * pyattr(self, \"q3\")) * pyattr(pyattr(self, \"N\"), \"z\")) / length))", e)
  .run("expected <- list(tup(pyattr(self, \"pA\"), pO_force), tup(pyattr(self, \"pB\"), pI_force))", e)
  expect_equal(.case("pycall(pyattr(self, \"pathway\"), \"to_loads\", pyattr(self, \"F\"))", e), "[(pA, - F*q1(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.x + F*q2(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.y - 2*F*q3(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.z), (pB, F*q1(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.x - F*q2(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.y + 2*F*q3(t)/sqrt(q1(t)^2 + q2(t)^2 + 4*q3(t)^2)*N.z)]")
})

test_that("mechanics/tests/test_pathway.py::TestObstacleSetPathway::test_valid_constructor[0] matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("num_attachments <- 3", e)
  .run("attachments <- lapply(pyiter(tup(\"pO\", \"pA\", \"pI\")), function(name) PhysPoint(name))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"pO\", PhysPoint(\"pO\"))", e)
  .run("pysetattr(self, \"pI\", PhysPoint(\"pI\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"qd\", dynamicsymbols(\"q\", 1))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("instance <- pydocall(ObstacleSetPathway, list(), attachments)", e)
  expect_equal(.case("pyisinstance(instance, ObstacleSetPathway)", e), "True")
  expect_equal(.case("pyhasattr(instance, \"attachments\")", e), "True")
  expect_equal(.case("length(pyattr(instance, \"attachments\"))", e), "3")
})

