test_that("mechanics/tests/test_pathway.py::TestObstacleSetPathway::test_static_pathway_to_loads matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"pO\", PhysPoint(\"pO\"))", e)
  .run("pysetattr(self, \"pI\", PhysPoint(\"pI\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"qd\", dynamicsymbols(\"q\", 1))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("pycall(pyattr(self, \"pA\"), \"set_pos\", pyattr(self, \"pO\"), pyattr(pyattr(self, \"N\"), \"x\"))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pO\"), pyattr(pyattr(self, \"N\"), \"y\"))", e)
  .run("pycall(pyattr(self, \"pI\"), \"set_pos\", pyattr(self, \"pO\"), pyattr(pyattr(self, \"N\"), \"z\"))", e)
  .run("pathway <- ObstacleSetPathway(pyattr(self, \"pO\"), pyattr(self, \"pA\"), pyattr(self, \"pB\"), pyattr(self, \"pI\"))", e)
  .run("expected <- list(Force(pyattr(self, \"pO\"), ((-pyattr(self, \"F\")) * pyattr(pyattr(self, \"N\"), \"x\"))), Force(pyattr(self, \"pA\"), (pyattr(self, \"F\") * pyattr(pyattr(self, \"N\"), \"x\"))), Force(pyattr(self, \"pA\"), (((pyattr(self, \"F\") * sqrt(S(2))) / 2) * (pyattr(pyattr(self, \"N\"), \"x\") - pyattr(pyattr(self, \"N\"), \"y\")))), Force(pyattr(self, \"pB\"), (((pyattr(self, \"F\") * sqrt(S(2))) / 2) * (pyattr(pyattr(self, \"N\"), \"y\") - pyattr(pyattr(self, \"N\"), \"x\")))), Force(pyattr(self, \"pB\"), (((pyattr(self, \"F\") * sqrt(S(2))) / 2) * (pyattr(pyattr(self, \"N\"), \"y\") - pyattr(pyattr(self, \"N\"), \"z\")))), Force(pyattr(self, \"pI\"), (((pyattr(self, \"F\") * sqrt(S(2))) / 2) * (pyattr(pyattr(self, \"N\"), \"z\") - pyattr(pyattr(self, \"N\"), \"y\")))))", e)
  expect_equal(.case("pycall(pathway, \"to_loads\", pyattr(self, \"F\"))", e), "[(pO, - F*N.x), (pA, F*N.x), (pA, sqrt(2)*F/2*N.x - sqrt(2)*F/2*N.y), (pB, - sqrt(2)*F/2*N.x + sqrt(2)*F/2*N.y), (pB, sqrt(2)*F/2*N.y - sqrt(2)*F/2*N.z), (pI, - sqrt(2)*F/2*N.y + sqrt(2)*F/2*N.z)]")
})

test_that("mechanics/tests/test_pathway.py::TestObstacleSetPathway::test_2D_pathway_length matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"pO\", PhysPoint(\"pO\"))", e)
  .run("pysetattr(self, \"pI\", PhysPoint(\"pI\"))", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"qd\", dynamicsymbols(\"q\", 1))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("pycall(pyattr(self, \"pA\"), \"set_pos\", pyattr(self, \"pO\"), (-(pyattr(pyattr(self, \"N\"), \"x\") + pyattr(pyattr(self, \"N\"), \"y\"))))", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pO\"), ((cos(pyattr(self, \"q\")) * pyattr(pyattr(self, \"N\"), \"x\")) - ((sin(pyattr(self, \"q\")) + 1) * pyattr(pyattr(self, \"N\"), \"y\"))))", e)
  .run("pycall(pyattr(self, \"pI\"), \"set_pos\", pyattr(self, \"pO\"), ((sin(pyattr(self, \"q\")) * pyattr(pyattr(self, \"N\"), \"x\")) + ((cos(pyattr(self, \"q\")) - 1) * pyattr(pyattr(self, \"N\"), \"y\"))))", e)
  .run("pathway <- ObstacleSetPathway(pyattr(self, \"pO\"), pyattr(self, \"pA\"), pyattr(self, \"pB\"), pyattr(self, \"pI\"))", e)
  .run("expected <- ((2 * sqrt(S(2))) + sqrt((2 + (2 * cos(pyattr(self, \"q\"))))))", e)
  expect_equal(.case("pycall((pyattr(pathway, \"length\") - expected), \"simplify\")", e), "0")
})

