test_that("mechanics/tests/test_pathway.py::TestWrappingPathway::test_valid_constructor matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"r\", Symbol(\"r\", positive = TRUE))", e)
  .run("pysetattr(self, \"pO\", PhysPoint(\"pO\"))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"ax\", pyattr(pyattr(self, \"N\"), \"z\"))", e)
  .run("pysetattr(self, \"sphere\", WrappingSphere(pyattr(self, \"r\"), pyattr(self, \"pO\")))", e)
  .run("pysetattr(self, \"cylinder\", WrappingCylinder(pyattr(self, \"r\"), pyattr(self, \"pO\"), pyattr(self, \"ax\")))", e)
  .run("pysetattr(self, \"pathway\", WrappingPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\"), pyattr(self, \"cylinder\")))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("instance <- WrappingPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\"), pyattr(self, \"cylinder\"))", e)
  expect_equal(.case("pyisinstance(instance, WrappingPathway)", e), "True")
  expect_equal(.case("pyhasattr(instance, \"attachments\")", e), "True")
  expect_equal(.case("length(pyattr(instance, \"attachments\"))", e), "2")
  expect_equal(.case("pyisinstance(pyget(pyattr(instance, \"attachments\"), 0), PhysPoint)", e), "True")
  expect_equal(.case("pyget(pyattr(instance, \"attachments\"), 0)", e), "pA")
  expect_equal(.case("pyisinstance(pyget(pyattr(instance, \"attachments\"), 1), PhysPoint)", e), "True")
  expect_equal(.case("pyget(pyattr(instance, \"attachments\"), 1)", e), "pB")
  expect_equal(.case("pyhasattr(instance, \"geometry\")", e), "True")
  expect_equal(.case("pyisinstance(pyattr(instance, \"geometry\"), WrappingGeometryBase)", e), "True")
  expect_equal(.case("pyattr(instance, \"geometry\")", e), "WrappingCylinder(radius=r, point=pO, axis=N.z)")
})

