  .run("pysetattr(self, \"pathway\", WrappingPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\"), pyattr(self, \"cylinder\")))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  expect_equal(.case("WrappingPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\"), geometry)", e), "ERR TypeError: Value N.x passed to `geometry` was of type <class 'sympy.physics.vector.vector.Vector'>, must be <class 'sympy.physics.mechanics.wrapping_geometry.WrappingGeometryBase'>.")
})

