test_that("mechanics/tests/test_pathway.py::TestWrappingPathway::test_2D_pathway_on_cylinder_length matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"pA\", PhysPoint(\"pA\"))", e)
  .run("pysetattr(self, \"pB\", PhysPoint(\"pB\"))", e)
  .run("pysetattr(self, \"r\", Symbol(\"r\", positive = TRUE))", e)
  .run("pysetattr(self, \"pO\", PhysPoint(\"pO\"))", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"ax\", pyattr(pyattr(self, \"N\"), \"z\"))", e)
  .run("pysetattr(self, \"sphere\", WrappingSphere(pyattr(self, \"r\"), pyattr(self, \"pO\")))", e)
  .run("pysetattr(self, \"cylinder\", WrappingCylinder(pyattr(self, \"r\"), pyattr(self, \"pO\"), pyattr(self, \"ax\")))", e)
  .run("pysetattr(self, \"pathway\", WrappingPathway(pyattr(self, \"pA\"), pyattr(self, \"pB\"), pyattr(self, \"cylinder\")))", e)
  .run("pysetattr(self, \"F\", Symbol(\"F\"))", e)
  .run("q <- dynamicsymbols(\"q\")", e)
  .run("pA_pos <- (pyattr(self, \"r\") * pyattr(pyattr(self, \"N\"), \"x\"))", e)
  .run("pB_pos <- (pyattr(self, \"r\") * ((cos(q) * pyattr(pyattr(self, \"N\"), \"x\")) + (sin(q) * pyattr(pyattr(self, \"N\"), \"y\"))))", e)
  .run("pycall(pyattr(self, \"pA\"), \"set_pos\", pyattr(self, \"pO\"), pA_pos)", e)
  .run("pycall(pyattr(self, \"pB\"), \"set_pos\", pyattr(self, \"pO\"), pB_pos)", e)
  .run("expected <- (pyattr(self, \"r\") * sqrt(pypow(q, 2)))", e)
  expect_equal(.case("pysimplify((pyattr(pyattr(self, \"pathway\"), \"length\") - expected))", e), "0")
})

test_that("mechanics/tests/test_pathway.py::TestWrappingPathway::test_2D_pathway_on_cylinder_extension_velocity matches SymPy", {
