test_that("mechanics/tests/test_rigidbody.py::test_rigidbody_default matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("b <- RigidBody(\"B\")", e)
  .run("I <- pydocall(inertia, list(pyattr(b, \"frame\")), pysymbols(\"B_ixx B_iyy B_izz B_ixy B_iyz B_izx\"))", e)
  expect_equal(.case("pyattr(b, \"name\")", e), "B")
  expect_equal(.case("pyattr(b, \"mass\")", e), "B_mass")
  expect_equal(.case("pyattr(pyattr(b, \"masscenter\"), \"name\")", e), "B_masscenter")
  expect_equal(.case("pyattr(b, \"inertia\")", e), "(B_ixx*(B_frame.x|B_frame.x) + B_ixy*(B_frame.x|B_frame.y) + B_izx*(B_frame.x|B_frame.z) + B_ixy*(B_frame.y|B_frame.x) + B_iyy*(B_frame.y|B_frame.y) + B_iyz*(B_frame.y|B_frame.z) + B_izx*(B_frame.z|B_frame.x) + B_iyz*(B_frame.z|B_frame.y) + B_izz*(B_frame.z|B_frame.z), B_masscenter)")
  expect_equal(.case("pyattr(b, \"central_inertia\")", e), "B_ixx*(B_frame.x|B_frame.x) + B_ixy*(B_frame.x|B_frame.y) + B_izx*(B_frame.x|B_frame.z) + B_ixy*(B_frame.y|B_frame.x) + B_iyy*(B_frame.y|B_frame.y) + B_iyz*(B_frame.y|B_frame.z) + B_izx*(B_frame.z|B_frame.x) + B_iyz*(B_frame.z|B_frame.y) + B_izz*(B_frame.z|B_frame.z)")
  expect_equal(.case("pyattr(pyattr(b, \"frame\"), \"name\")", e), "B_frame")
  expect_equal(.case("pycall(b, \"__str__\")", e), "B")
  expect_equal(.case("pycall(b, \"__repr__\")", e), "RigidBody('B', masscenter=B_masscenter, frame=B_frame, mass=B_mass, inertia=Inertia(dyadic=B_ixx*(B_frame.x|B_frame.x) + B_ixy*(B_frame.x|B_frame.y) + B_izx*(B_frame.x|B_frame.z) + B_ixy*(B_frame.y|B_frame.x) + B_iyy*(B_frame.y|B_frame.y) + B_iyz*(B_frame.y|B_frame.z) + B_izx*(B_frame.z|B_frame.x) + B_iyz*(B_frame.z|B_frame.y) + B_izz*(B_frame.z|B_frame.z), point=B_masscenter))")
})

test_that("mechanics/tests/test_rigidbody.py::test_rigidbody matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(pysymbols(\"m m2 v1 v2 v3 omega\")); m <- .tmp[[1]]; m2 <- .tmp[[2]]; v1 <- .tmp[[3]]; v2 <- .tmp[[4]]; v3 <- .tmp[[5]]; omega <- .tmp[[6]]", e)
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("A2 <- ReferenceFrame(\"A2\")", e)
  .run("P <- PhysPoint(\"P\")", e)
  .run("P2 <- PhysPoint(\"P2\")", e)
  .run("I <- PhysDyadic(0)", e)
  .run("I2 <- PhysDyadic(0)", e)
  .run("B <- RigidBody(\"B\", P, A, m, tup(I, P))", e)
  expect_equal(.case("pyattr(B, \"mass\")", e), "m")
  expect_equal(.case("pyattr(B, \"frame\")", e), "A")
  expect_equal(.case("pyattr(B, \"masscenter\")", e), "P")
  expect_equal(.case("pyattr(B, \"inertia\")", e), "(0, P)")
  .run("pysetattr(B, \"mass\", m2)", e)
  .run("pysetattr(B, \"frame\", A2)", e)
  .run("pysetattr(B, \"masscenter\", P2)", e)
  .run("pysetattr(B, \"inertia\", tup(I2, pyattr(B, \"masscenter\")))", e)
  expect_equal(.case("RigidBody(P, P, A, m, tup(I, P))", e), "ERR TypeError: Supply a valid name.")
  expect_equal(.case("RigidBody(\"B\", P, P, m, tup(I, P))", e), "ERR TypeError: RigidBody frame must be a ReferenceFrame object.")
  expect_equal(.case("RigidBody(\"B\", P, A, m, tup(P, P))", e), "ERR TypeError: RigidBody inertia must be a tuple of the form (Dyadic, Point).")
  expect_equal(.case("RigidBody(\"B\", P, A, m, tup(I, I))", e), "ERR TypeError: RigidBody inertia must be a tuple of the form (Dyadic, Point).")
  expect_equal(.case("pycall(B, \"__str__\")", e), "B")
  expect_equal(.case("pyattr(B, \"mass\")", e), "m2")
  expect_equal(.case("pyattr(B, \"frame\")", e), "A2")
  expect_equal(.case("pyattr(B, \"masscenter\")", e), "P2")
  expect_equal(.case("pyattr(B, \"inertia\")", e), "(0, P2)")
  expect_equal(.case("pyisinstance(pyattr(B, \"inertia\"), Inertia)", e), "True")
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("pycall(P2, \"set_vel\", N, (((v1 * pyattr(N, \"x\")) + (v2 * pyattr(N, \"y\"))) + (v3 * pyattr(N, \"z\"))))", e)
  expect_equal(.case("pycall(B, \"linear_momentum\", N)", e), "m2*v1*N.x + m2*v2*N.y + m2*v3*N.z")
})

test_that("mechanics/tests/test_rigidbody.py::test_rigidbody2 matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"M v r omega g h\")); M <- .tmp[[1]]; v <- .tmp[[2]]; r <- .tmp[[3]]; omega <- .tmp[[4]]; g <- .tmp[[5]]; h <- .tmp[[6]]", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run("b <- ReferenceFrame(\"b\")", e)
  .run("pycall(b, \"set_ang_vel\", N, (omega * pyattr(b, \"x\")))", e)
  .run("P <- PhysPoint(\"P\")", e)
  .run("I <- outer_sym(pyattr(b, \"x\"), pyattr(b, \"x\"))", e)
  .run("Inertia_tuple <- tup(I, P)", e)
  .run("B <- RigidBody(\"B\", P, b, M, Inertia_tuple)", e)
  .run("pycall(P, \"set_vel\", N, (v * pyattr(b, \"x\")))", e)
  expect_equal(.case("pycall(B, \"angular_momentum\", P, N)", e), "omega(t)*b.x")
  .run("O <- PhysPoint(\"O\")", e)
  .run("pycall(O, \"set_vel\", N, (v * pyattr(b, \"x\")))", e)
  .run("pycall(P, \"set_pos\", O, (r * pyattr(b, \"y\")))", e)
  expect_equal(.case("pycall(B, \"angular_momentum\", O, N)", e), "omega(t)*b.x - M(t)*r(t)*v(t)*b.z")
  .run("pysetattr(B, \"potential_energy\", ((M * g) * h))", e)
  expect_equal(.case("pyattr(B, \"potential_energy\")", e), "M(t)*g(t)*h(t)")
  expect_equal(.case("pyexpand((2 * pycall(B, \"kinetic_energy\", N)))", e), "M(t)*v(t)^2 + omega(t)^2")
})

test_that("mechanics/tests/test_rigidbody.py::test_rigidbody3 matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run(".tmp <- pylist(dynamicsymbols(\"q1:5\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; q4 <- .tmp[[4]]", e)
  .run(".tmp <- pylist(pysymbols(\"p1:4\")); p1 <- .tmp[[1]]; p2 <- .tmp[[2]]; p3 <- .tmp[[3]]", e)
  .run("m <- pysymbols(\"m\")", e)
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("B <- pycall(A, \"orientnew\", \"B\", \"axis\", list(q1, pyattr(A, \"x\")))", e)
  .run("O <- PhysPoint(\"O\")", e)
  .run("pycall(O, \"set_vel\", A, (((q2 * pyattr(A, \"x\")) + (q3 * pyattr(A, \"y\"))) + (q4 * pyattr(A, \"z\"))))", e)
  .run("P <- pycall(O, \"locatenew\", \"P\", (((p1 * pyattr(B, \"x\")) + (p2 * pyattr(B, \"y\"))) + (p3 * pyattr(B, \"z\"))))", e)
  .run("pycall(P, \"v2pt_theory\", O, A, B)", e)
  .run("I <- outer_sym(pyattr(B, \"x\"), pyattr(B, \"x\"))", e)
  .run("rb1 <- RigidBody(\"rb1\", P, B, m, tup(I, P))", e)
  .run("rb2 <- RigidBody(\"rb2\", P, B, m, tup((I + inertia_of_point_mass(m, pycall(P, \"pos_from\", O), B)), O))", e)
  expect_equal(.case("pyattr(rb1, \"central_inertia\")", e), "(B.x|B.x)")
  expect_equal(.case("pycall(rb1, \"angular_momentum\", O, A)", e), "(-m*(p2*sin(q1(t)) + p3*cos(q1(t)))*q3(t) + m*(p2*cos(q1(t)) - p3*sin(q1(t)))*q4(t))*A.x + (-m*p1*q4(t) + m*(p2*sin(q1(t)) + p3*cos(q1(t)))*q2(t))*A.y + (m*p1*q3(t) - m*(p2*cos(q1(t)) - p3*sin(q1(t)))*q2(t))*A.z + (m*p2^2*Derivative(q1(t), t) + m*p3^2*Derivative(q1(t), t) + Derivative(q1(t), t))*B.x - m*p1*p2*Derivative(q1(t), t)*B.y - m*p1*p3*Derivative(q1(t), t)*B.z")
})

test_that("mechanics/tests/test_rigidbody.py::test_rigidbody_inertia matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("N <- ReferenceFrame(\"N\")", e)
  .run(".tmp <- pylist(pysymbols(\"m, I_x, I_y, I_z, a, b\")); m <- .tmp[[1]]; Ix <- .tmp[[2]]; Iy <- .tmp[[3]]; Iz <- .tmp[[4]]; a <- .tmp[[5]]; b <- .tmp[[6]]", e)
  .run("Io <- inertia(N, Ix, Iy, Iz)", e)
  .run("o <- PhysPoint(\"o\")", e)
  .run("p <- pycall(o, \"locatenew\", \"p\", ((a * pyattr(N, \"x\")) + (b * pyattr(N, \"y\"))))", e)
  .run("R <- RigidBody(\"R\", o, N, m, tup(Io, p))", e)
  .run("I_check <- inertia(N, (Ix - (pypow(b, 2) * m)), (Iy - (pypow(a, 2) * m)), (Iz - (m * (pypow(a, 2) + pypow(b, 2)))), ((m * a) * b))", e)
  expect_equal(.case("pyisinstance(pyattr(R, \"inertia\"), Inertia)", e), "True")
  expect_equal(.case("pyattr(R, \"inertia\")", e), "(I_x*(N.x|N.x) + I_y*(N.y|N.y) + I_z*(N.z|N.z), p)")
  expect_equal(.case("pyattr(R, \"central_inertia\")", e), "(I_x - b^2*m)*(N.x|N.x) + (I_y - a^2*m)*(N.y|N.y) + (I_z - m*(a^2 + b^2))*(N.z|N.z) + a*b*m*(N.x|N.y) + a*b*m*(N.y|N.x)")
  .run("pysetattr(R, \"central_inertia\", Io)", e)
  expect_equal(.case("pyattr(R, \"inertia\")", e), "(I_x*(N.x|N.x) + I_y*(N.y|N.y) + I_z*(N.z|N.z), o)")
  expect_equal(.case("pyattr(R, \"central_inertia\")", e), "I_x*(N.x|N.x) + I_y*(N.y|N.y) + I_z*(N.z|N.z)")
  .run("pysetattr(R, \"inertia\", tup(Io, p))", e)
  expect_equal(.case("pyattr(R, \"inertia\")", e), "(I_x*(N.x|N.x) + I_y*(N.y|N.y) + I_z*(N.z|N.z), p)")
  expect_equal(.case("pyattr(R, \"central_inertia\")", e), "(I_x - b^2*m)*(N.x|N.x) + (I_y - a^2*m)*(N.y|N.y) + (I_z - m*(a^2 + b^2))*(N.z|N.z) + a*b*m*(N.x|N.y) + a*b*m*(N.y|N.x)")
  .run("pysetattr(R, \"inertia\", Inertia(Io, o))", e)
  expect_equal(.case("pyattr(R, \"inertia\")", e), "(I_x*(N.x|N.x) + I_y*(N.y|N.y) + I_z*(N.z|N.z), o)")
})

test_that("mechanics/tests/test_rigidbody.py::test_parallel_axis matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("N <- ReferenceFrame(\"N\")", e)
  .run(".tmp <- pylist(pysymbols(\"m, I_x, I_y, I_z, a, b\")); m <- .tmp[[1]]; Ix <- .tmp[[2]]; Iy <- .tmp[[3]]; Iz <- .tmp[[4]]; a <- .tmp[[5]]; b <- .tmp[[6]]", e)
  .run("Io <- inertia(N, Ix, Iy, Iz)", e)
  .run("o <- PhysPoint(\"o\")", e)
  .run("p <- pycall(o, \"locatenew\", \"p\", ((a * pyattr(N, \"x\")) + (b * pyattr(N, \"y\"))))", e)
  .run("R <- RigidBody(\"R\", o, N, m, tup(Io, o))", e)
  .run("Ip <- pycall(R, \"parallel_axis\", p)", e)
  .run("Ip_expected <- inertia(N, (Ix + (m * pypow(b, 2))), (Iy + (m * pypow(a, 2))), (Iz + (m * (pypow(a, 2) + pypow(b, 2)))), ixy = (((-m) * a) * b))", e)
  expect_equal(.case("Ip", e), "(I_x + b^2*m)*(N.x|N.x) + (I_y + a^2*m)*(N.y|N.y) + (I_z + m*(a^2 + b^2))*(N.z|N.z) - a*b*m*(N.x|N.y) - a*b*m*(N.y|N.x)")
  .run("A <- ReferenceFrame(\"A\")", e)
  .run("pycall(A, \"orient_axis\", N, pyattr(N, \"z\"), 1)", e)
  expect_equal(.case("pysimplify(pycall((pycall(R, \"parallel_axis\", p, A) - Ip_expected), \"to_matrix\", A))", e), "Matrix([[0, 0, 0], [0, 0, 0], [0, 0, 0]])")
})

