  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pt <- Particle(\"particle\")", e)
  expect_equal(.case("pyclassmethod(\"System\", \"from_newtonian\")(pt)", e), "ERR TypeError: A Particle has no frame so cannot act as the Newtonian.")
})

