test_that("mechanics/tests/test_system_class.py::TestSystem::test_add_joints matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run(".tmp <- pylist(dynamicsymbols(\"q1:5 u1:4\")); q1 <- .tmp[[1]]; q2 <- .tmp[[2]]; q3 <- .tmp[[3]]; q4 <- .tmp[[4]]; u1 <- .tmp[[5]]; u2 <- .tmp[[6]]; u3 <- .tmp[[7]]", e)
  .run(".tmp <- pylist(pysymbols(\"rb1:6\", cls = RigidBody)); rb1 <- .tmp[[1]]; rb2 <- .tmp[[2]]; rb3 <- .tmp[[3]]; rb4 <- .tmp[[4]]; rb5 <- .tmp[[5]]", e)
  .run("J1 <- PinJoint(\"J1\", rb1, rb2, q1, u1)", e)
  .run("J2 <- PrismaticJoint(\"J2\", rb2, rb3, q2, u2)", e)
  .run("J3 <- PinJoint(\"J3\", rb3, rb4, q3, u3)", e)
  .run("J_lag <- PinJoint(\"J_lag\", rb4, rb5, q4, pycall(q4, \"diff\", t))", e)
  .run("system <- System()", e)
  .run("pycall(system, \"add_joints\", J1)", e)
  expect_equal(.case("pyattr(system, \"joints\")", e), "(PinJoint: J1  parent: rb1  child: rb2,)")
  expect_equal(.case("pyattr(system, \"bodies\")", e), "(rb1, rb2)")
  expect_equal(.case("pyattr(system, \"q_ind\")", e), "Matrix([[q1(t)]])")
  expect_equal(.case("pyattr(system, \"u_ind\")", e), "Matrix([[u1(t)]])")
  expect_equal(.case("pyattr(system, \"kdes\")", e), "Matrix([[u1(t) - Derivative(q1(t), t)]])")
  .run("pycall(system, \"add_bodies\", rb4)", e)
  .run("pycall(system, \"add_coordinates\", q3)", e)
  .run("pycall(system, \"add_kdes\", (u3 - pycall(q3, \"diff\", t)))", e)
  .run("pycall(system, \"add_joints\", J3)", e)
  expect_equal(.case("pyattr(system, \"joints\")", e), "(PinJoint: J1  parent: rb1  child: rb2, PinJoint: J3  parent: rb3  child: rb4)")
  expect_equal(.case("pyattr(system, \"bodies\")", e), "(rb1, rb2, rb4, rb3)")
  expect_equal(.case("pyattr(system, \"q_ind\")", e), "Matrix([[q1(t)], [q3(t)]])")
  expect_equal(.case("pyattr(system, \"u_ind\")", e), "Matrix([[u1(t)], [u3(t)]])")
  expect_equal(.case("pyattr(system, \"kdes\")", e), "Matrix([[u1(t) - Derivative(q1(t), t)], [u3(t) - Derivative(q3(t), t)]])")
  .run("pycall(system, \"add_kdes\", (-(u2 - pycall(q2, \"diff\", t))))", e)
  .run("pycall(system, \"add_joints\", J2)", e)
  expect_equal(.case("pyattr(system, \"joints\")", e), "(PinJoint: J1  parent: rb1  child: rb2, PinJoint: J3  parent: rb3  child: rb4, PrismaticJoint: J2  parent: rb2  child: rb3)")
  expect_equal(.case("pyattr(system, \"bodies\")", e), "(rb1, rb2, rb4, rb3)")
  expect_equal(.case("pyattr(system, \"q_ind\")", e), "Matrix([[q1(t)], [q3(t)], [q2(t)]])")
  expect_equal(.case("pyattr(system, \"u_ind\")", e), "Matrix([[u1(t)], [u3(t)], [u2(t)]])")
  expect_equal(.case("pyattr(system, \"kdes\")", e), "Matrix([[u1(t) - Derivative(q1(t), t)], [u3(t) - Derivative(q3(t), t)], [-u2(t) + Derivative(q2(t), t)]])")
  .run("pycall(system, \"add_joints\", J_lag)", e)
  expect_equal(.case("pyattr(system, \"joints\")", e), "(PinJoint: J1  parent: rb1  child: rb2, PinJoint: J3  parent: rb3  child: rb4, PrismaticJoint: J2  parent: rb2  child: rb3, PinJoint: J_lag  parent: rb4  child: rb5)")
  expect_equal(.case("pyattr(system, \"bodies\")", e), "(rb1, rb2, rb4, rb3, rb5)")
  expect_equal(.case("pyattr(system, \"q_ind\")", e), "Matrix([[q1(t)], [q3(t)], [q2(t)], [q4(t)]])")
  expect_equal(.case("pyattr(system, \"u_ind\")", e), "Matrix([[u1(t)], [u3(t)], [u2(t)], [Derivative(q4(t), t)]])")
  expect_equal(.case("pyattr(system, \"kdes\")", e), "Matrix([[u1(t) - Derivative(q1(t), t)], [u3(t) - Derivative(q3(t), t)], [-u2(t) + Derivative(q2(t), t)]])")
  expect_equal(.case("pyslice(pyattr(system, \"q_dep\"), NULL, NULL, NULL)", e), "[]")
  expect_equal(.case("pyslice(pyattr(system, \"u_dep\"), NULL, NULL, NULL)", e), "[]")
})

test_that("mechanics/tests/test_system_class.py::TestSystemExamples::test_cart_pendulum_kanes matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run(".tmp <- pylist(pysymbols(\"g l mc mp k\")); g <- .tmp[[1]]; l <- .tmp[[2]]; mc <- .tmp[[3]]; mp <- .tmp[[4]]; k <- .tmp[[5]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"F qp qc up uc\")); `F` <- .tmp[[1]]; qp <- .tmp[[2]]; qc <- .tmp[[3]]; up <- .tmp[[4]]; uc <- .tmp[[5]]", e)
  .run("rail <- RigidBody(\"rail\")", e)
  .run("cart <- RigidBody(\"cart\", mass = mc)", e)
  .run("bob <- Particle(\"bob\", mass = mp)", e)
  .run("bob_frame <- ReferenceFrame(\"bob_frame\")", e)
  .run("system <- pyclassmethod(\"System\", \"from_newtonian\")(rail)", e)
  expect_equal(.case("pyattr(system, \"bodies\")", e), "(rail,)")
  expect_equal(.case("pyattr(system, \"frame\")", e), "rail_frame")
  expect_equal(.case("pyattr(system, \"fixed_point\")", e), "rail_masscenter")
  .run("slider <- PrismaticJoint(\"slider\", rail, cart, qc, uc, joint_axis = pyattr(rail, \"x\"))", e)
  .run("pin <- PinJoint(\"pin\", cart, bob, qp, up, joint_axis = pyattr(cart, \"z\"), child_interframe = bob_frame, child_point = (l * pyattr(bob_frame, \"y\")))", e)
  .run("pycall(system, \"add_joints\", slider, pin)", e)
  expect_equal(.case("pyattr(system, \"joints\")", e), "(PrismaticJoint: slider  parent: rail  child: cart, PinJoint: pin  parent: cart  child: bob)")
  expect_equal(.case("pycall(system, \"get_joint\", \"slider\")", e), "PrismaticJoint: slider  parent: rail  child: cart")
  expect_equal(.case("pycall(system, \"get_body\", \"bob\")", e), "bob")
  .run("pycall(system, \"apply_uniform_gravity\", ((-g) * pyattr(system, \"y\")))", e)
  .run("pycall(system, \"add_loads\", tup(pyattr(cart, \"masscenter\"), (`F` * pyattr(rail, \"x\"))))", e)
  .run("pycall(system, \"add_actuators\", TorqueActuator((k * qp), pyattr(cart, \"z\"), bob_frame, cart))", e)
  .run("pycall(system, \"validate_system\")", e)
  .run("pycall(system, \"form_eoms\")", e)
  expect_equal(.case("pyisinstance(pyattr(system, \"eom_method\"), KanesMethod)", e), "True")
  expect_equal(.case("pysimplify((pyattr(system, \"mass_matrix\") - Matrix(list(list((mp + mc), ((mp * l) * cos(qp))), list(((mp * l) * cos(qp)), (mp * pypow(l, 2)))))))", e), "Matrix([[0, 0], [0, 0]])")
  expect_equal(.case("pysimplify((pyattr(system, \"forcing\") - Matrix(list(list(((((mp * l) * pypow(up, 2)) * sin(qp)) + `F`)), list((((((-mp) * g) * l) * sin(qp)) + (k * qp)))))))", e), "Matrix([[0], [0]])")
  .run("pycall(system, \"add_holonomic_constraints\", sympify(pycall(pycall(pyattr(bob, \"masscenter\"), \"pos_from\", pyattr(rail, \"masscenter\")), \"dot\", pyattr(system, \"x\"))))", e)
  expect_equal(.case("pyis(pyattr(system, \"eom_method\"), NULL)", e), "True")
})

test_that("mechanics/tests/test_system_class.py::TestSystemExamples::test_cart_pendulum_lagrange matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run(".tmp <- pylist(pysymbols(\"g l mc mp k\")); g <- .tmp[[1]]; l <- .tmp[[2]]; mc <- .tmp[[3]]; mp <- .tmp[[4]]; k <- .tmp[[5]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"F qp qc\")); `F` <- .tmp[[1]]; qp <- .tmp[[2]]; qc <- .tmp[[3]]", e)
  .run(".tmp <- pylist(dynamicsymbols(\"qp qc\", 1)); qpd <- .tmp[[1]]; qcd <- .tmp[[2]]", e)
  .run("rail <- RigidBody(\"rail\")", e)
  .run("cart <- RigidBody(\"cart\", mass = mc)", e)
  .run("bob <- Particle(\"bob\", mass = mp)", e)
  .run("bob_frame <- ReferenceFrame(\"bob_frame\")", e)
  .run("system <- pyclassmethod(\"System\", \"from_newtonian\")(rail)", e)
  expect_equal(.case("pyattr(system, \"bodies\")", e), "(rail,)")
  expect_equal(.case("pyattr(system, \"frame\")", e), "rail_frame")
  expect_equal(.case("pyattr(system, \"fixed_point\")", e), "rail_masscenter")
  .run("slider <- PrismaticJoint(\"slider\", rail, cart, qc, qcd, joint_axis = pyattr(rail, \"x\"))", e)
  .run("pin <- PinJoint(\"pin\", cart, bob, qp, qpd, joint_axis = pyattr(cart, \"z\"), child_interframe = bob_frame, child_point = (l * pyattr(bob_frame, \"y\")))", e)
  .run("pycall(system, \"add_joints\", slider, pin)", e)
  expect_equal(.case("pyattr(system, \"joints\")", e), "(PrismaticJoint: slider  parent: rail  child: cart, PinJoint: pin  parent: cart  child: bob)")
  expect_equal(.case("pycall(system, \"get_joint\", \"slider\")", e), "PrismaticJoint: slider  parent: rail  child: cart")
  expect_equal(.case("pycall(system, \"get_body\", \"bob\")", e), "bob")
  .run("for (body in pyiter(pyattr(system, \"bodies\"))) { pysetattr(body, \"potential_energy\", ((pyattr(body, \"mass\") * g) * pycall(pycall(pyattr(body, \"masscenter\"), \"pos_from\", pyattr(system, \"fixed_point\")), \"dot\", pyattr(system, \"y\")))) }", e)
  .run("pycall(system, \"add_loads\", tup(pyattr(cart, \"masscenter\"), (`F` * pyattr(rail, \"x\"))))", e)
  .run("pycall(system, \"add_actuators\", TorqueActuator((k * qp), pyattr(cart, \"z\"), bob_frame, cart))", e)
  .run("pycall(system, \"validate_system\", LagrangesMethod)", e)
  .run("pycall(system, \"form_eoms\", LagrangesMethod)", e)
  expect_equal(.case("pysimplify((pyattr(system, \"mass_matrix\") - Matrix(list(list((mp + mc), ((mp * l) * cos(qp))), list(((mp * l) * cos(qp)), (mp * pypow(l, 2)))))))", e), "Matrix([[0, 0], [0, 0]])")
  expect_equal(.case("pysimplify((pyattr(system, \"forcing\") - Matrix(list(list(((((mp * l) * pypow(qpd, 2)) * sin(qp)) + `F`)), list((((((-mp) * g) * l) * sin(qp)) + (k * qp)))))))", e), "Matrix([[0], [0]])")
  .run("pycall(system, \"add_holonomic_constraints\", sympify(pycall(pycall(pyattr(bob, \"masscenter\"), \"pos_from\", pyattr(rail, \"masscenter\")), \"dot\", pyattr(system, \"x\"))))", e)
  expect_equal(.case("pyis(pyattr(system, \"eom_method\"), NULL)", e), "True")
})

.menv <- new.env(parent = H)
local({ s <- get(".pv_state", envir = ns); s$simp <- FALSE; s$t <- NULL })
try(.run(".tmp <- pylist(dynamicsymbols(\"x y u v lambda\")); x <- .tmp[[1]]; y <- .tmp[[2]]; u <- .tmp[[3]]; v <- .tmp[[4]]; lam <- .tmp[[5]]; .tmp <- pylist(pysymbols(\"m l g\")); m <- .tmp[[1]]; l <- .tmp[[2]]; g <- .tmp[[3]]; dyn_implicit_mat <- Matrix(list(list(1, 0, ((-x) / m)), list(0, 1, ((-y) / m)), list(0, 0, (pypow(l, 2) / m)))); dyn_implicit_rhs <- Matrix(list(0, 0, ((pypow(u, 2) + pypow(v, 2)) - (g * y)))); comb_implicit_mat <- Matrix(list(list(1, 0, 0, 0, 0), list(0, 1, 0, 0, 0), list(0, 0, 1, 0, ((-x) / m)), list(0, 0, 0, 1, ((-y) / m)), list(0, 0, 0, 0, (pypow(l, 2) / m)))); comb_implicit_rhs <- Matrix(list(u, v, 0, 0, ((pypow(u, 2) + pypow(v, 2)) - (g * y)))); kin_explicit_rhs <- Matrix(list(u, v)); comb_explicit_rhs <- pycall(comb_implicit_mat, \"LUsolve\", comb_implicit_rhs); theta <- atan((x / y)); N <- ReferenceFrame(\"N\"); A <- pycall(N, \"orientnew\", \"A\", \"Axis\", list(theta, pyattr(N, \"z\"))); O <- PhysPoint(\"O\"); P <- pycall(O, \"locatenew\", \"P\", (l * pyattr(A, \"x\"))); Pa <- Particle(\"Pa\", P, m); bodies <- list(Pa); loads <- list(tup(P, ((g * m) * pyattr(N, \"x\")))); PE <- pysymbols(\"PE\"); out_eqns <- pydict(list(PE), list(((m * g) * (l + y)))); alg_con <- list(2); alg_con_full <- list(4); coordinates <- tup(x, y, lam); speeds <- tup(u, v); states <- tup(x, y, u, v, lam); coord_idxs <- tup(0, 1); speed_idxs <- tup(2, 3)", .menv), silent = TRUE)
test_that("mechanics/tests/test_system.py::test_form_1 matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("symsystem1 <- SymbolicSystem(states, comb_explicit_rhs, alg_con = alg_con_full, output_eqns = out_eqns, coord_idxs = coord_idxs, speed_idxs = speed_idxs, bodies = bodies, loads = loads)", e)
  expect_equal(.case("pyattr(symsystem1, \"coordinates\")", e), "Matrix([[x(t)], [y(t)]])")
  expect_equal(.case("pyattr(symsystem1, \"speeds\")", e), "Matrix([[u(t)], [v(t)]])")
  expect_equal(.case("pyattr(symsystem1, \"states\")", e), "Matrix([[x(t)], [y(t)], [u(t)], [v(t)], [lambda(t)]])")
  expect_equal(.case("pyattr(symsystem1, \"alg_con\")", e), "[4]")
  .run("inter <- comb_explicit_rhs", e)
  expect_equal(.case("pysimplify((pyattr(symsystem1, \"comb_explicit_rhs\") - inter))", e), "Matrix([[0], [0], [0], [0], [0]])")
  expect_equal(.case("pyset(pycall(symsystem1, \"dynamic_symbols\"))", e), "{lambda(t), u(t), v(t), x(t), y(t)}")
  expect_equal(.case("pyset(pycall(symsystem1, \"constant_symbols\"))", e), "{g, l, m}")
  expect_equal(.case("pyattr(symsystem1, \"output_eqns\")", e), "{PE: g*m*(l + y(t))}")
  expect_equal(.case("pyattr(symsystem1, \"bodies\")", e), "(Pa,)")
  expect_equal(.case("pyattr(symsystem1, \"loads\")", e), "((P, g*m*N.x),)")
})

