test_that("mechanics/tests/test_system.py::test_not_specified_errors matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("\"This test will cover errors that arise from trying to access attributes\\\\n    that were not specified upon object creation or were specified on creation\\\\n    and the user tries to recalculate them.\"", e)
  .run("symsystem1 <- SymbolicSystem(states, comb_explicit_rhs)", e)
  expect_equal(.case("pyattr(symsystem1, \"comb_implicit_mat\")", e), "ERR AttributeError: comb_implicit_mat is not specified for equations of motion form [1].")
  expect_equal(.case("pyattr(symsystem1, \"comb_implicit_rhs\")", e), "ERR AttributeError: comb_implicit_mat is not specified for equations of motion in form [1].")
  expect_equal(.case("pyattr(symsystem1, \"dyn_implicit_mat\")", e), "ERR AttributeError: dyn_implicit_mat is not specified for equations of motion form [1] or [2].")
  expect_equal(.case("pyattr(symsystem1, \"dyn_implicit_rhs\")", e), "ERR AttributeError: dyn_implicit_rhs is not specified for equations of motion form [1] or [2].")
  expect_equal(.case("pyattr(symsystem1, \"kin_explicit_rhs\")", e), "ERR AttributeError: kin_explicit_rhs is not specified for equations of motion form [1] or [2].")
  expect_equal(.case("pycall(symsystem1, \"compute_explicit_form\")", e), "ERR AttributeError: comb_explicit_rhs is already formed.")
  .run("symsystem2 <- SymbolicSystem(coordinates, comb_implicit_rhs, speeds = speeds, mass_matrix = comb_implicit_mat)", e)
  expect_equal(.case("pyattr(symsystem2, \"dyn_implicit_mat\")", e), "ERR AttributeError: dyn_implicit_mat is not specified for equations of motion form [1] or [2].")
  expect_equal(.case("pyattr(symsystem2, \"dyn_implicit_rhs\")", e), "ERR AttributeError: dyn_implicit_rhs is not specified for equations of motion form [1] or [2].")
  expect_equal(.case("pyattr(symsystem2, \"kin_explicit_rhs\")", e), "ERR AttributeError: kin_explicit_rhs is not specified for equations of motion form [1] or [2].")
  expect_equal(.case("pyattr(symsystem1, \"coordinates\")", e), "ERR AttributeError: The coordinates were not specified.")
  expect_equal(.case("pyattr(symsystem1, \"speeds\")", e), "ERR AttributeError: The speeds were not specified.")
  expect_equal(.case("pyattr(symsystem1, \"bodies\")", e), "ERR AttributeError: bodies were not specified for the system.")
  expect_equal(.case("pyattr(symsystem1, \"loads\")", e), "ERR AttributeError: loads were not specified for the system.")
  expect_equal(.case("pyattr(symsystem2, \"comb_explicit_rhs\")", e), "ERR AttributeError: Please run .combute_explicit_form before attempting to access comb_explicit_rhs.")
})

.menv <- new.env(parent = H)
