try(.run("\"Tests for the ``sympy.physics.mechanics.wrapping_geometry.py`` module.\"; r <- Symbol(\"r\", positive = TRUE); x <- Symbol(\"x\"); q <- dynamicsymbols(\"q\"); N <- ReferenceFrame(\"N\")", .menv), silent = TRUE)
test_that("mechanics/tests/test_wrapping_geometry.py::TestWrappingSphere::test_valid_constructor matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("r <- Symbol(\"r\", positive = TRUE)", e)
  .run("pO <- PhysPoint(\"pO\")", e)
  .run("sphere <- WrappingSphere(r, pO)", e)
  expect_equal(.case("pyisinstance(sphere, WrappingSphere)", e), "True")
