test_that("mechanics/tests/test_wrapping_geometry.py::TestWrappingSphere::test_geodesic_end_vectors[2] matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("position_1 <- (r * pyattr(N, \"y\"))", e)
  .run("position_2 <- ((((sqrt(S(2)) / 2) * r) * pyattr(N, \"x\")) - (((sqrt(S(2)) / 2) * r) * pyattr(N, \"y\")))", e)
  .run("vector_1 <- pyattr(N, \"x\")", e)
  .run("vector_2 <- (((sqrt(S(2)) / 2) * pyattr(N, \"x\")) + ((sqrt(S(2)) / 2) * pyattr(N, \"y\")))", e)
  .run("r <- Symbol(\"r\", positive = TRUE)", e)
  .run("pO <- PhysPoint(\"pO\")", e)
  .run("sphere <- WrappingSphere(r, pO)", e)
  .run("p1 <- PhysPoint(\"p1\")", e)
  .run("pycall(p1, \"set_pos\", pO, position_1)", e)
  .run("p2 <- PhysPoint(\"p2\")", e)
  .run("pycall(p2, \"set_pos\", pO, position_2)", e)
  .run("expected <- tup(vector_1, vector_2)", e)
  expect_equal(.case("pycall(sphere, \"geodesic_end_vectors\", p1, p2)", e), "(N.x, sqrt(2)*(-r^2/2 + sqrt(2)*r*(sqrt(2)*r/2 + r)/2)/(2*Abs(r^2/2 - sqrt(2)*r*(sqrt(2)*r/2 + r)/2))*N.x + sqrt(2)*(-r^2/2 + sqrt(2)*r*(sqrt(2)*r/2 + r)/2)/(2*Abs(r^2/2 - sqrt(2)*r*(sqrt(2)*r/2 + r)/2))*N.y)")
})

