  .run("expected <- tup(vector_1, vector_2)", e)
  expect_equal(.case("pycall(sphere, \"geodesic_end_vectors\", p1, p2)", e), "(N.y, sqrt(3)/2*N.x - 1/2*N.y)")
})

test_that("mechanics/tests/test_wrapping_geometry.py::TestWrappingSphere::test_geodesic_end_vectors[4] matches SymPy", {
