  .run("self <- pyself()", e)
  .run("axis <- pyattr(N, \"z\")", e)
  .run("position_1 <- (r * pyattr(N, \"x\"))", e)
  .run("position_2 <- (r * pyattr(N, \"y\"))", e)
  .run("vector_1 <- pyattr(N, \"y\")", e)
  .run("vector_2 <- pyattr(N, \"x\")", e)
  .run("r <- Symbol(\"r\", positive = TRUE)", e)
  .run("pO <- PhysPoint(\"pO\")", e)
