  .run("expected <- tup(vector_1, vector_2)", e)
  .run("end_vectors <- pytup(lapply(pyiter(pycall(cylinder, \"geodesic_end_vectors\", p1, p2)), function(end_vector) pycall(end_vector, \"simplify\")))", e)
  expect_equal(.case("end_vectors", e), "(N.y, N.x)")
})

