test_that("mechanics/tests/test_wrapping_geometry.py::TestWrappingCone::test_valid_constructor matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("N <- ReferenceFrame(\"N\")", e)
  .run(".tmp <- pylist(tup(Symbol(\"alpha\"), PhysPoint(\"p0\"), pyattr(N, \"z\"))); alpha <- .tmp[[1]]; apex <- .tmp[[2]]; axis <- .tmp[[3]]", e)
  .run("cone <- WrappingCone(alpha, apex, axis)", e)
  expect_equal(.case("pyisinstance(cone, WrappingCone)", e), "True")
  expect_equal(.case("pyhasattr(cone, \"alpha\")", e), "True")
  expect_equal(.case("pyattr(cone, \"alpha\")", e), "alpha")
  expect_equal(.case("pyhasattr(cone, \"apex\")", e), "True")
  expect_equal(.case("pyattr(cone, \"apex\")", e), "p0")
  expect_equal(.case("pyhasattr(cone, \"axis\")", e), "True")
  expect_equal(.case("pyattr(cone, \"axis\")", e), "N.z")
})

