  .run("axis <- pyattr(N, \"x\")", e)
  .run("alpha <- (S_Pi / 4)", e)
  .run("position_1 <- (pyattr(N, \"y\") + pyattr(N, \"x\"))", e)
  .run("position_2 <- (pyattr(N, \"z\") + (2 * pyattr(N, \"x\")))", e)
  .run("apex <- PhysPoint(\"p0\")", e)
  .run("cone <- WrappingCone(alpha, apex, axis)", e)
  .run("p1 <- PhysPoint(\"p1\")", e)
  .run("pycall(p1, \"set_pos\", apex, position_1)", e)
  .run("p2 <- PhysPoint(\"p2\")", e)
  .run("pycall(p2, \"set_pos\", apex, position_2)", e)
  .run(".tmp <- pylist(pycall(cone, \"geodesic_end_vectors\", p1, p2)); v1_calc <- .tmp[[1]]; v2_calc <- .tmp[[2]]", e)
  .run("pos1 <- pycall(p1, \"pos_from\", apex)", e)
  .run("pos2 <- pycall(p2, \"pos_from\", apex)", e)
  .run("z1 <- pycall(pos1, \"dot\", axis)", e)
  .run("z2 <- pycall(pos2, \"dot\", axis)", e)
  .run("s1 <- (z1 / cos(alpha))", e)
  .run("s2 <- (z2 / cos(alpha))", e)
  .run("L <- pycall(cone, \"geodesic_length\", p1, p2)", e)
  .run("n1 <- pycall((pos1 - (z1 * axis)), \"normalize\")", e)
  .run("n2 <- pycall((pos2 - (z2 * axis)), \"normalize\")", e)
  .run("central <- acos(pycancel(pycall(n1, \"dot\", n2)))", e)
  .run("delta_u <- (central * sin(alpha))", e)
  .run("g1 <- pycall(pos1, \"normalize\")", e)
  .run("c1 <- pycall(axis, \"cross\", n1)", e)
  .run("g2 <- pycall(pos2, \"normalize\")", e)
  .run("c2 <- pycall(axis, \"cross\", n2)", e)
  .run("v1_radial_comp <- (((s2 * cos(delta_u)) - s1) / L)", e)
  .run("v1_circ_comp <- ((s2 * sin(delta_u)) / L)", e)
  .run("expected_v1 <- ((v1_radial_comp * g1) + (v1_circ_comp * c1))", e)
  .run("v2_radial_comp <- (((s1 * cos(delta_u)) - s2) / L)", e)
  .run("v2_circ_comp <- (((-s1) * sin(delta_u)) / L)", e)
  .run("expected_v2 <- ((v2_radial_comp * g2) + (v2_circ_comp * c2))", e)
  expect_equal(.case("v1_calc", e), "sqrt(2)*(-sqrt(2) + 2*sqrt(2)*cos(sqrt(2)*pi/4))/(2*sqrt(10 - 8*cos(sqrt(2)*pi/4)))*N.x + sqrt(2)*(-sqrt(2) + 2*sqrt(2)*cos(sqrt(2)*pi/4))/(2*sqrt(10 - 8*cos(sqrt(2)*pi/4)))*N.y + 2*sqrt(2)*sin(sqrt(2)*pi/4)/sqrt(10 - 8*cos(sqrt(2)*pi/4))*N.z")
  expect_equal(.case("v2_calc", e), "2*sqrt(5)*(-2*sqrt(2) + sqrt(2)*cos(sqrt(2)*pi/4))/(5*sqrt(10 - 8*cos(sqrt(2)*pi/4)))*N.x + sqrt(2)*sin(sqrt(2)*pi/4)/sqrt(10 - 8*cos(sqrt(2)*pi/4))*N.y + sqrt(5)*(-2*sqrt(2) + sqrt(2)*cos(sqrt(2)*pi/4))/(5*sqrt(10 - 8*cos(sqrt(2)*pi/4)))*N.z")
})

test_that("mechanics/tests/test_wrapping_geometry.py::TestWrappingCone::test_geodesic_end_vectors[3] matches SymPy", {
  e <- new.env(parent = .menv)
