  .run("self <- pyself()", e)
  .run("position <- (pyattr(N, \"x\") + pyattr(N, \"z\"))", e)
  .run("apex <- PhysPoint(\"p0\")", e)
  .run("cone <- WrappingCone((S_Pi / 6), apex, pyattr(N, \"z\"))", e)
  .run("p1 <- PhysPoint(\"p1\")", e)
